export type Status = 'Backlog' | 'ToDo' | 'InProgress' | 'Done';

export interface System {
  id: string;
  name: string;
  description: string;
  subsystems: Subsystem[];
}

export interface Subsystem {
  id: string;
  name: string;
  description: string;
  features: Feature[];
  systemId: string; // Parent reference
}

export interface Feature {
  id: string;
  name: string;
  description: string;
  subsystemId: string; // Parent reference
}

export interface Requirement {
  id: string;
  title: string;
  description: string;
  status: Status;
  priority: 'Low' | 'Medium' | 'High';
  systemId: string;
  subsystemId: string;
  featureId: string;
  startDate?: string;
  completionDate?: string;
  createdAt: number;
}

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  constructor() {
    this.loadFromStorage();

    // Auto-save effect
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }
}

import { Injectable } from '@angular/core';
import { GoogleGenAI } from '@google/genai';

@Injectable({
  providedIn: 'root'
})
export class AiService {
  private ai: GoogleGenAI;

  constructor() {
    // Initialize Gemini Client
    // process.env.API_KEY is guaranteed to be available in this environment
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async generateRequirements(systemName: string, featureName: string): Promise<any[]> {
    try {
      const prompt = `
        Act as a Senior Business Analyst. Generate 3 detailed software requirements for a system named "${systemName}" and specifically for the feature "${featureName}".
        Return a JSON array where each object has:
        - "title": Short summary (max 10 words)
        - "description": Detailed description including acceptance criteria.
        - "priority": "Low", "Medium", or "High"

        Ensure the response is strictly a JSON array. Do not include markdown code blocks.
      `;

      const response = await this.ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          responseMimeType: 'application/json'
        }
      });

      const text = response.text;
      if (!text) return [];

      return JSON.parse(text);
    } catch (e) {
      console.error('AI Generation Failed', e);
      return [];
    }
  }

  async suggestSubsystems(systemName: string, description: string): Promise<any[]> {
    try {
       const prompt = `
        Analyze the system "${systemName}": ${description}.
        Suggest 3 logical subsystems that would be part of this architecture.
        Return a JSON array where each object has:
        - "name": Subsystem name
        - "description": Brief description

        Ensure response is JSON array.
      `;

      const response = await this.ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          responseMimeType: 'application/json'
        }
      });

      const text = response.text;
      return text ? JSON.parse(text) : [];
    } catch (e) {
      return [];
    }
  }
}

import { Component, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="h-full flex flex-col bg-white border-r border-gray-200">
      <!-- Header -->
      <div class="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
        <h2 class="font-bold text-gray-700">Systems</h2>
        <button (click)="isAddingSystem.set(true)" class="text-blue-600 hover:text-blue-800 p-1 rounded hover:bg-blue-50">
