            <path fill-rule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clip-rule="evenodd" />
          </svg>
        </button>
      </div>

      <!-- Add System Input -->
      @if (isAddingSystem()) {
        <div class="p-4 bg-blue-50 border-b border-blue-100">
          <input 
            type="text" 
            [(ngModel)]="newSystemName" 
            placeholder="System Name"
            class="w-full text-sm border-gray-300 rounded-md shadow-sm focus:border-blue-500 focus:ring-blue-500 mb-2 p-2 border"
          >
          <div class="flex gap-2">
            <button (click)="createSystem()" class="text-xs bg-blue-600 text-white px-2 py-1 rounded">Save</button>
            <button (click)="isAddingSystem.set(false)" class="text-xs text-gray-500 hover:text-gray-700 px-2 py-1">Cancel</button>
          </div>
        </div>
      }

      <!-- Tree View -->
      <div class="flex-1 overflow-y-auto p-2">
        @for (system of dataService.systems(); track system.id) {
          <div class="mb-2">
            <!-- System Node -->
            <div 
              class="flex items-center gap-2 p-2 rounded cursor-pointer transition-colors group"
              [class.bg-blue-50]="dataService.selectedSystemId() === system.id && !dataService.selectedSubsystemId()"
              (click)="selectSystem(system.id)"
            >
              <span class="text-gray-400">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                   <path fill-rule="evenodd" d="M2 5a2 2 0 012-2h12a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2V5zm14 1a1 1 0 11-2 0 1 1 0 012 0zM2 13a2 2 0 012-2h12a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2v-2zm14 1a1 1 0 11-2 0 1 1 0 012 0z" clip-rule="evenodd" />
                </svg>
              </span>
              <span class="font-semibold text-gray-800 text-sm flex-1 truncate">{{ system.name }}</span>
              <button 
                (click)="addingSubsystemTo.set(system.id); $event.stopPropagation()"
                class="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-blue-600"
                title="Add Subsystem"
              >
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clip-rule="evenodd" /></svg>
              </button>
            </div>

            <!-- Add Subsystem Input -->
            @if (addingSubsystemTo() === system.id) {
               <div class="ml-6 mr-2 mb-2 p-2 bg-gray-50 rounded border border-gray-200">
                 <div class="flex justify-between items-center mb-1">
                    <span class="text-xs font-semibold text-gray-500">New Subsystem</span>
                    <button (click)="suggestSubsystems(system)" class="text-xs text-purple-600 flex items-center gap-1 hover:underline">
                        <svg class="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3zM6 8a2 2 0 11-4 0 2 2 0 014 0zM16 18v-3a5.972 5.972 0 00-.75-2.906A3.005 3.005 0 0119 15v3h-3zM4.75 12.094A5.973 5.973 0 004 15v3H1v-3a3 3 0 013.75-2.906z" /></svg>
                        AI Suggest
                    </button>
                 </div>

                 @if(isGenerating()) {
                   <div class="text-xs text-purple-500 animate-pulse mb-2">Thinking...</div>
                 }

                <input type="text" [(ngModel)]="newSubsystemName" class="w-full text-xs p-1 border rounded mb-1" placeholder="Name">
                <div class="flex gap-2">
                  <button (click)="createSubsystem(system.id)" class="text-xs bg-gray-800 text-white px-2 py-0.5 rounded">Add</button>
                  <button (click)="addingSubsystemTo.set(null)" class="text-xs text-gray-500">Cancel</button>
                </div>
              </div>
