            <!-- Subsystems List -->
            <div class="ml-4 border-l-2 border-gray-100 pl-2">
              @for (sub of system.subsystems; track sub.id) {
                <div class="mb-1">
                   <div 
                    class="flex items-center gap-2 p-1.5 rounded cursor-pointer hover:bg-gray-50 group"
                    [class.bg-blue-50]="dataService.selectedSubsystemId() === sub.id"
                    (click)="selectSubsystem(sub.id)"
                   >
                    <span class="text-gray-400">
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor">
                           <path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" />
                        </svg>
                    </span>
                    <span class="text-sm text-gray-600 truncate flex-1">{{ sub.name }}</span>
                     <button 
                        (click)="addingFeatureTo.set(sub.id); $event.stopPropagation()"
                        class="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-green-600"
                        title="Add Feature"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clip-rule="evenodd" /></svg>
                      </button>
                   </div>

                   <!-- Add Feature Input -->
                   @if (addingFeatureTo() === sub.id) {
                     <div class="ml-4 mt-1 mb-2 p-2 bg-green-50 rounded border border-green-100">
                        <input type="text" [(ngModel)]="newFeatureName" class="w-full text-xs p-1 border rounded mb-1" placeholder="Feature Name">
                        <div class="flex gap-2">
                          <button (click)="createFeature(system.id, sub.id)" class="text-xs bg-green-600 text-white px-2 py-0.5 rounded">Add Feature</button>
                          <button (click)="addingFeatureTo.set(null)" class="text-xs text-gray-500">Cancel</button>
                        </div>
                     </div>
                   }

                   <!-- Features List -->
                   <div class="ml-4 border-l border-gray-100 pl-2">
                      @for (feat of sub.features; track feat.id) {
                         <div 
                            class="p-1 text-xs text-gray-500 hover:text-blue-600 cursor-pointer flex items-center gap-2 rounded hover:bg-gray-50"
                            [class.bg-blue-100]="dataService.selectedFeatureId() === feat.id"
                            [class.text-blue-700]="dataService.selectedFeatureId() === feat.id"
                            (click)="selectFeature(feat.id)"
                         >
                            <span class="w-1.5 h-1.5 rounded-full bg-green-400"></span>
                            {{ feat.name }}
                         </div>
                      }
                   </div>
                </div>
              }
            </div>
          </div>
        }
      </div>
    </div>
  `
})
export class HierarchyNavComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);
  isGenerating = signal(false);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(id: string) {
    this.dataService.selectedSubsystemId.set(id);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(id: string) {
    this.dataService.selectedFeatureId.set(id);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  async suggestSubsystems(system: any) {
    this.isGenerating.set(true);
    const suggestions = await this.aiService.suggestSubsystems(system.name, system.description);
    this.isGenerating.set(false);

    // Auto add suggestions for demo speed
    suggestions.forEach(s => {
      this.dataService.addSubsystem(system.id, s.name, s.description);
    });
    this.addingSubsystemTo.set(null); // Close the manual box if open
  }
}

import { Component, inject, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, Feature } from '../models/data.models';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="h-full flex flex-col">
      <!-- Toolbar -->
      <div class="h-16 border-b border-gray-200 bg-white flex items-center justify-between px-6 shadow-sm z-10">
        <div>
           <h1 class="text-xl font-bold text-gray-800">
             @if(selectedFeature()) {
               Feature: {{ selectedFeature()?.name }}
             } @else if (selectedSubsystem()) {
               Subsystem: {{ selectedSubsystem()?.name }}
             } @else if (selectedSystem()) {
               System: {{ selectedSystem()?.name }}
             } @else {
               All Requirements
             }
           </h1>
           <p class="text-xs text-gray-500">
             {{ filteredRequirements().length }} items found
           </p>
        </div>

        <button 
          [disabled]="!canAddRequirement()"
          (click)="openAddModal()"
          class="bg-blue-600 hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed text-white px-4 py-2 rounded-lg font-medium flex items-center gap-2 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fill-rule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clip-rule="evenodd" />
          </svg>
          New Requirement
        </button>
      </div>

      <!-- Board Area -->
      <div class="flex-1 overflow-x-auto p-6">
        <div class="flex gap-6 h-full min-w-[1000px]">

          <!-- Columns -->
          @for (status of columns; track status) {
            <div class="flex-1 flex flex-col bg-gray-100 rounded-xl max-w-xs">
              <!-- Column Header -->
              <div class="p-3 font-semibold text-gray-700 border-b border-gray-200 flex justify-between items-center sticky top-0 bg-gray-100 rounded-t-xl z-0">
                <span>{{ formatStatus(status) }}</span>
                <span class="bg-gray-200 text-gray-600 text-xs px-2 py-0.5 rounded-full">
                  {{ getRequirementsByStatus(status).length }}
                </span>
              </div>

              <!-- Cards Container -->
              <div class="flex-1 overflow-y-auto p-2 space-y-3">
                @for (req of getRequirementsByStatus(status); track req.id) {
                  <div 
                    class="bg-white p-3 rounded-lg shadow-sm border border-gray-200 hover:shadow-md transition-all cursor-move group relative"
                    draggable="true"
                    (dragstart)="onDragStart($event, req.id)"
                  >
                    <!-- Priority Stripe -->
                    <div [class]="'absolute left-0 top-0 bottom-0 w-1 rounded-l-lg ' + getPriorityColor(req.priority)"></div>

                    <div class="pl-2">
                        <h3 class="font-medium text-gray-800 text-sm mb-1 leading-snug">{{ req.title }}</h3>
                        <p class="text-xs text-gray-500 line-clamp-2 mb-2">{{ req.description }}</p>

                        <div class="flex justify-between items-center mt-2">
                           <span class="text-[10px] text-gray-400 font-mono">
                             {{ req.id.slice(0, 4) }}
                           </span>
                           <!-- Quick Move for non-drag environments/accessibility -->
                           <div class="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              @if (status !== 'Backlog') {
                                <button (click)="moveStatus(req, -1)" class="p-1 hover:bg-gray-100 rounded text-gray-500" title="Move Back">
                                    <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path></svg>
                                </button>
                              }
                              @if (status !== 'Done') {
                                <button (click)="moveStatus(req, 1)" class="p-1 hover:bg-gray-100 rounded text-gray-500" title="Move Forward">
                                    <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                                </button>
                              }
                           </div>
                        </div>
                    </div>
                  </div>
                }
              </div>

              <!-- Drop Zone Overlay (Implicit via dragover handling on container) -->
              <div 
                class="h-10 m-2 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center text-gray-400 text-xs"
                (dragover)="onDragOver($event)"
                (drop)="onDrop($event, status)"
              >
                Drop here
              </div>

            </div>
          }

        </div>
      </div>
    </div>

    <!-- Create Modal -->
    @if (showModal()) {
      <div class="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
        <div class="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">

          <div class="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50">
             <h2 class="text-xl font-bold text-gray-800">Create Requirements</h2>
             <button (click)="showModal.set(false)" class="text-gray-400 hover:text-gray-600">
               <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
             </button>
          </div>

          <div class="p-6 overflow-y-auto">

             <!-- AI Section -->
             <div class="mb-8 bg-gradient-to-r from-purple-50 to-blue-50 p-4 rounded-xl border border-purple-100">
                <div class="flex items-start gap-4">
                   <div class="p-2 bg-white rounded-full shadow-sm text-purple-600">
                      <svg class="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3zM6 8a2 2 0 11-4 0 2 2 0 014 0zM16 18v-3a5.972 5.972 0 00-.75-2.906A3.005 3.005 0 0119 15v3h-3zM4.75 12.094A5.973 5.973 0 004 15v3H1v-3a3 3 0 013.75-2.906z" /></svg>
                   </div>
                   <div class="flex-1">
                      <h3 class="font-semibold text-purple-900">AI Generator</h3>
                      <p class="text-sm text-purple-700 mb-3">Generate requirements automatically based on the selected feature context.</p>

                      @if (isGenerating()) {
                        <div class="flex items-center gap-2 text-sm text-purple-600">
                           <svg class="animate-spin h-4 w-4 text-purple-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
