                   <textarea rows="3" [(ngModel)]="newReqDesc" class="w-full border-gray-300 rounded-lg shadow-sm focus:ring-blue-500 focus:border-blue-500 p-2 border" placeholder="Acceptance criteria, details..."></textarea>
