  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');

  // Platform Data
  platforms = Object.keys(AI_PLATFORMS);
  availableModels = computed(() => AI_PLATFORMS[this.exportPlatform()] || []);

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
  );

  selectedSubsystem = computed(() => {
    const sys = this.selectedSystem();
    return sys?.subsystems.find(s => s.id === this.dataService.selectedSubsystemId());
  });

  selectedFeature = computed(() => {
    const sub = this.selectedSubsystem();
    return sub?.features.find(f => f.id === this.dataService.selectedFeatureId());
  });

  // Current Documentation based on selection level
  currentReadme = computed(() => {
    if (this.selectedFeature()) return this.selectedFeature()!.readme || '';
    if (this.selectedSubsystem()) return this.selectedSubsystem()!.readme || '';
    if (this.selectedSystem()) return this.selectedSystem()!.readme || '';
    return '';
  });

  // Check if AI is available
  aiEnabled = computed(() => this.aiService.isConfigured());

  // Effect to update editor when selection changes
  constructor() {
    effect(() => {
        this.editableReadme.set(this.currentReadme());
    });

    // Set default model when platform changes
    effect(() => {
        const models = AI_PLATFORMS[this.exportPlatform()];
        if (models && models.length > 0) {
            this.exportModel.set(models[0]);
        }
    });
  }

  saveReadme() {
    const content = this.editableReadme();
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (feat && sub && sys) {
        this.dataService.updateFeatureReadme(sys.id, sub.id, feat.id, content);
    } else if (sub && sys) {
        this.dataService.updateSubsystemReadme(sys.id, sub.id, content);
    } else if (sys) {
        this.dataService.updateSystemReadme(sys.id, content);
    }
  }

  triggerImport(mode: 'append' | 'replace', input: HTMLInputElement) {
    this.importMode = mode;
    input.value = ''; // Reset to allow re-selecting same file
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input.files?.length) return;

    const file = input.files[0];
    const reader = new FileReader();

    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (this.importMode === 'replace') {
             if (!this.editableReadme() || confirm('This will replace the current documentation. Continue?')) {
                 this.editableReadme.set(text);
             }
        } else {
             const current = this.editableReadme();
             this.editableReadme.set(current ? current + '\n\n' + text : text);
        }
    };
    reader.readAsText(file);
  }

  filteredRequirements = computed(() => {
    let reqs = this.dataService.requirements();
    const fId = this.dataService.selectedFeatureId();
    const sId = this.dataService.selectedSubsystemId();
    const sysId = this.dataService.selectedSystemId();

    // Context Filtering
    if (fId) reqs = reqs.filter(r => r.featureId === fId);
    else if (sId) reqs = reqs.filter(r => r.subsystemId === sId);
    else if (sysId) reqs = reqs.filter(r => r.systemId === sysId);

    // Search Filtering
    const term = this.searchTerm().toLowerCase();
    if (term) {
        reqs = reqs.filter(r => 
            r.title.toLowerCase().includes(term) || 
            r.description.toLowerCase().includes(term)
        );
    }

    return reqs;
  });

  canAddRequirement = computed(() => !!this.selectedFeature());

  openAddModal() {
    this.editingReqId.set(null);
    this.newReqTitle = '';
    this.newReqDesc = '';
    this.newReqPriority = 'Medium';
    this.showModal.set(true);
  }

  openEditModal(req: Requirement) {
    this.editingReqId.set(req.id);
    this.newReqTitle = req.title;
    this.newReqDesc = req.description;
    this.newReqPriority = req.priority;
    this.showModal.set(true);
  }

  openAiModal() {
    if (!this.aiEnabled()) {
        this.apiKeyInput = '';
        this.showApiKeyModal.set(true);
        return;
    }
    this.userStoryPrompt = '';
    this.showAiModal.set(true);
  }

  configureApiKey() {
    if (this.apiKeyInput.trim()) {
        const success = this.aiService.configure(this.apiKeyInput.trim());
        if (success) {
            this.showApiKeyModal.set(false);
            // Do not automatically open the AI generation modal
        } else {
            alert('Failed to configure AI service.');
        }
    }
  }

  async generateAiRequirements() {
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (!feat || !sub || !sys || !this.userStoryPrompt.trim()) return;

    this.isGenerating.set(true);
    const context = `System: ${sys.name}, Subsystem: ${sub.name}, Feature: ${feat.name}`;

    let docStack = '';
    if (sys.readme) docStack += `[SYSTEM DOCS]:\n${sys.readme}\n\n`;
    if (sub.readme) docStack += `[SUBSYSTEM DOCS]:\n${sub.readme}\n\n`;
    if (feat.readme) docStack += `[FEATURE DOCS]:\n${feat.readme}\n\n`;

    try {
      const generated = await this.aiService.generateRequirements(context, docStack, this.userStoryPrompt);

      generated.forEach(req => {
        this.dataService.addRequirement({
          title: req.title,
          description: req.description,
          priority: req.priority,
          status: 'Backlog',
          systemId: sys.id,
          subsystemId: sub.id,
          featureId: feat.id
        });
      });

      this.showAiModal.set(false);
    } finally {
      this.isGenerating.set(false);
    }
  }

  saveManual() {
    // Edit mode
    const editId = this.editingReqId();
    if (editId) {
        this.dataService.updateRequirement(editId, {
            title: this.newReqTitle,
            description: this.newReqDesc,
            priority: this.newReqPriority
        });
        this.showModal.set(false);
        return;
    }

    // Create mode
    const feat = this.selectedFeature();
    if (!feat) return;

    this.dataService.addRequirement({
      title: this.newReqTitle,
      description: this.newReqDesc,
      priority: this.newReqPriority,
      status: 'Backlog',
      systemId: this.dataService.selectedSystemId()!,
      subsystemId: this.dataService.selectedSubsystemId()!,
      featureId: feat.id
    });
    this.showModal.set(false);
  }

  // --- Export Logic ---

  copyPrompt(req?: Requirement) {
    const sys = this.selectedSystem();
    const sub = this.selectedSubsystem();
    const feat = this.selectedFeature();

    let content = 'PROJECT CONTEXT\n===============\n';
    if (sys) content += `System: ${sys.name}\nDescription: ${sys.description}\n\n`;
    if (sub) content += `Subsystem: ${sub.name}\nDescription: ${sub.description}\n\n`;
    if (feat) content += `Feature: ${feat.name}\nDescription: ${feat.description}\n\n`;

    content += 'DOCUMENTATION\n=============\n';
    if (sys?.readme) content += `[SYSTEM: ${sys.name}]\n${sys.readme}\n\n`;
    if (sub?.readme) content += `[SUBSYSTEM: ${sub.name}]\n${sub.readme}\n\n`;
    if (feat?.readme) content += `[FEATURE: ${feat.name}]\n${feat.readme}\n\n`;

    if (req) {
      content += 'SELECTED REQUIREMENT\n====================\n';
      content += `Title: ${req.title}\n`;
      content += `Status: ${req.status}\n`;
      content += `Priority: ${req.priority}\n`;
      content += `Description:\n${req.description}\n`;

      content += '\nTASK\n====\n';
      content += `[Generate implementation steps, test cases, or code for: "${req.title}"]\n`;

      this.exportParentId.set(req.id);
      this.exportParentType.set('Requirement');
      this.exportParentName.set(req.title);
    } else {
        content += 'TASK\n====\n';
        content += '[Enter instruction here, e.g., Generate test cases, Implement this feature, etc.]\n';

        // Determine parent scope
        if (feat) {
            this.exportParentId.set(feat.id);
            this.exportParentType.set('Feature');
            this.exportParentName.set(feat.name);
        } else if (sub) {
            this.exportParentId.set(sub.id);
            this.exportParentType.set('Subsystem');
            this.exportParentName.set(sub.name);
        } else if (sys) {
            this.exportParentId.set(sys.id);
            this.exportParentType.set('System');
            this.exportParentName.set(sys.name);
        }
    }

    this.exportContextText.set(content);
    this.showExportModal.set(true);
  }

  saveExportSession() {
      // 1. Save to DB
      this.dataService.addWorkSession({
          parentId: this.exportParentId(),
          parentType: this.exportParentType(),
          parentName: this.exportParentName(),
          context: this.exportContextText(),
          platform: this.exportPlatform(),
          model: this.exportModel(),
          status: 'Pending'
      });

      // 2. Copy to Clipboard
      navigator.clipboard.writeText(this.exportContextText()).then(() => {
          alert('Session Created! Context copied to clipboard.');
      }).catch(err => {
          console.error('Copy failed', err);
          alert('Session Created, but failed to copy text automatically.');
      });

      // 3. Close & Reset
      this.showExportModal.set(false);
  }
}

export type Status = 'Backlog' | 'ToDo' | 'InProgress' | 'Done';

export type FolderCategory = 'UI' | 'Service' | 'Library';

export interface SystemFolder {
  id: string;
  name: string;
  category: FolderCategory;
  note: string;
}

export interface System {
  id: string;
  name: string;
  description: string;
  readme?: string; // Context/Documentation
  subsystems: Subsystem[];
  folders: SystemFolder[];
}

export interface Subsystem {
  id: string;
  name: string;
  description: string;
  readme?: string; // Context/Documentation
  features: Feature[];
  systemId: string; // Parent reference
}

export interface Feature {
  id: string;
  name: string;
  description: string;
  readme?: string; // Context/Documentation
  subsystemId: string; // Parent reference
}

export interface Requirement {
  id: string;
  title: string;
  description: string;
  status: Status;
  priority: 'Low' | 'Medium' | 'High';
  systemId: string;
  subsystemId: string;
  featureId: string;
  startDate?: string;
  completionDate?: string;
  createdAt: number;
}

export interface WorkSession {
  id: string;
  parentId: string;
  parentType: 'System' | 'Subsystem' | 'Feature' | 'Requirement';
  parentName: string; // Snapshot for display
  context: string;
  platform: string;
  model: string;
  outcome?: string;
  status: 'Pending' | 'Completed';
  createdAt: number;
  updatedAt: number;
}

export const AI_PLATFORMS: Record<string, string[]> = {
  'Cursor': ['Claude 3.5 Sonnet', 'GPT-4o', 'DeepSeek R1', 'Gemini 1.5 Pro', 'Big Pickle'],
  'Windsurf': ['Cascade (Claude 3.5)', 'Cascade (GPT-4o)'],
  'Trae': ['Claude 3.5 Sonnet', 'GPT-4o'],
  'OpenCode': ['Default Model'],
  'Antigravity': ['Default Model'],
  'Replit': ['Replit Agent', 'Ghostwriter'],
  'Google IDX': ['Gemini 2.0 Flash', 'Gemini 1.5 Pro'],
  'VS Code (Copilot)': ['GPT-4o', 'Claude 3.5 Sonnet'],
  'Web (ChatGPT)': ['GPT-4o', 'o1', 'o3-mini'],
  'Web (Claude)': ['Claude 3.5 Sonnet', 'Claude 3 Opus'],
  'Web (Gemini)': ['Gemini Advanced', 'Gemini 2.5 Flash'],
  'Custom': ['Other']
};

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, computed, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, AI_PLATFORMS, FolderCategory } from '../models/data.models';
import { FormsModule } from '@angular/forms';
import { BoardViewComponent } from './board-view.component';
import { TableViewComponent } from './table-view.component';
import { WorkSessionViewComponent } from './work-session-view.component';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule, BoardViewComponent, TableViewComponent, WorkSessionViewComponent],
  templateUrl: './kanban-board.component.html'
})
export class KanbanBoardComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  viewMode = signal<'board' | 'table' | 'docs' | 'sessions'>('board');
  searchTerm = signal('');
  showModal = signal(false);
  showAiModal = signal(false);
  showApiKeyModal = signal(false);
  showExportModal = signal(false); // New modal for export
  isGenerating = signal(false);

  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');

  // Platform Data
  platforms = Object.keys(AI_PLATFORMS);
  availableModels = computed(() => AI_PLATFORMS[this.exportPlatform()] || []);

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // System Folders State
  newFolderName = signal('');
  newFolderCategory = signal<FolderCategory>('UI');
  newFolderNote = signal('');

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
