import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getRandomColor() {
    const colors = ['#EF4444', '#F97316', '#F59E0B', '#10B981', '#3B82F6', '#6366F1', '#8B5CF6', '#EC4899'];
    return colors[Math.floor(Math.random() * colors.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color: this.getRandomColor(),
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }
}

import { Component, inject, input, output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { Requirement, Status } from '../models/data.models';

@Component({
  selector: 'app-board-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './board-view.component.html'
})
export class BoardViewComponent {
  dataService = inject(DataService);
  requirements = input.required<Requirement[]>();
  copyReqPrompt = output<Requirement>();
  editReq = output<Requirement>();

  columns: Status[] = ['Backlog', 'ToDo', 'InProgress', 'Done'];
  draggedReqId: string | null = null;

  getRequirementsByStatus(status: Status) {
    return this.requirements().filter(r => r.status === status);
  }

  formatStatus(status: string) {
    return status.replace(/([A-Z])/g, ' $1').trim();
  }

  getPriorityColor(priority: string) {
    switch(priority) {
      case 'High': return 'bg-red-500';
      case 'Medium': return 'bg-yellow-500';
      case 'Low': return 'bg-blue-400';
      default: return 'bg-gray-300';
    }
  }

  deleteReq(id: string, event: Event) {
    event.stopPropagation();
    if(confirm('Delete requirement?')) {
      this.dataService.deleteRequirement(id);
    }
  }

  onCopy(req: Requirement, event: Event) {
    event.stopPropagation();
    this.copyReqPrompt.emit(req);
  }

  onEdit(req: Requirement, event: Event) {
      event.stopPropagation();
      this.editReq.emit(req);
  }

  // --- Drag and Drop Logic ---
  onDragStart(event: DragEvent, id: string) {
    this.draggedReqId = id;
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', id);
    }
  }

  onDragOver(event: DragEvent) {
    event.preventDefault(); 
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = 'move';
    }
  }

  onDrop(event: DragEvent, newStatus: Status) {
    event.preventDefault();
    const id = this.draggedReqId;
    if (id) {
      this.dataService.updateRequirementStatus(id, newStatus);
    }
    this.draggedReqId = null;
  }

  moveStatus(req: Requirement, direction: number) {
     const idx = this.columns.indexOf(req.status);
     const newIdx = idx + direction;
     if (newIdx >= 0 && newIdx < this.columns.length) {
        this.dataService.updateRequirementStatus(req.id, this.columns[newIdx]);
     }
  }
}

import { Component, inject, computed, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, AI_PLATFORMS, FolderCategory } from '../models/data.models';
import { FormsModule } from '@angular/forms';
import { BoardViewComponent } from './board-view.component';
import { TableViewComponent } from './table-view.component';
import { WorkSessionViewComponent } from './work-session-view.component';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule, BoardViewComponent, TableViewComponent, WorkSessionViewComponent],
  templateUrl: './kanban-board.component.html'
})
export class KanbanBoardComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  viewMode = signal<'board' | 'table' | 'docs' | 'sessions'>('board');
  searchTerm = signal('');
  showModal = signal(false);
  showAiModal = signal(false);
  showApiKeyModal = signal(false);
  showExportModal = signal(false); // New modal for export
  isGenerating = signal(false);

  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');
  includeInProgress = signal(false);
  pendingExportReqIds = signal<string[]>([]); // Store IDs to update status later

  // Platform Data
  platforms = Object.keys(AI_PLATFORMS);
  availableModels = computed(() => AI_PLATFORMS[this.exportPlatform()] || []);

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // System Folders State
  newFolderName = signal('');
  newFolderCategory = signal<FolderCategory>('UI');
  newFolderNote = signal('');

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
  );

  selectedSubsystem = computed(() => {
    const sys = this.selectedSystem();
    return sys?.subsystems.find(s => s.id === this.dataService.selectedSubsystemId());
  });

  selectedFeature = computed(() => {
    const sub = this.selectedSubsystem();
    return sub?.features.find(f => f.id === this.dataService.selectedFeatureId());
  });

  // Current Documentation based on selection level
  currentReadme = computed(() => {
    if (this.selectedFeature()) return this.selectedFeature()!.readme || '';
    if (this.selectedSubsystem()) return this.selectedSubsystem()!.readme || '';
    if (this.selectedSystem()) return this.selectedSystem()!.readme || '';
    return '';
  });

  // Check if AI is available
  aiEnabled = computed(() => this.aiService.isConfigured());

  // Effect to update editor when selection changes
  constructor() {
    effect(() => {
        this.editableReadme.set(this.currentReadme());
    });

    // Set default model when platform changes
    effect(() => {
        const models = AI_PLATFORMS[this.exportPlatform()];
        if (models && models.length > 0) {
            this.exportModel.set(models[0]);
        }
    });
  }

  saveReadme() {
    const content = this.editableReadme();
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (feat && sub && sys) {
        this.dataService.updateFeatureReadme(sys.id, sub.id, feat.id, content);
    } else if (sub && sys) {
        this.dataService.updateSubsystemReadme(sys.id, sub.id, content);
    } else if (sys) {
        this.dataService.updateSystemReadme(sys.id, content);
    }
  }

  // --- Folder Logic ---
  addFolder() {
    const sys = this.selectedSystem();
    if (sys && this.newFolderName().trim()) {
        this.dataService.addSystemFolder(sys.id, {
            name: this.newFolderName(),
            category: this.newFolderCategory(),
            note: this.newFolderNote()
        });
        this.newFolderName.set('');
        this.newFolderNote.set('');
        this.newFolderCategory.set('UI');
    }
  }

  deleteFolder(folderId: string) {
     const sys = this.selectedSystem();
     if (sys) {
         if (confirm('Delete this folder?')) {
            this.dataService.deleteSystemFolder(sys.id, folderId);
         }
     }
  }

  getCategoryClass(category: FolderCategory) {
      switch(category) {
          case 'UI': return 'bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300';
          case 'Service': return 'bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300';
          case 'Library': return 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300';
          default: return 'bg-gray-100 text-gray-800';
      }
  }

  triggerImport(mode: 'append' | 'replace', input: HTMLInputElement) {
    this.importMode = mode;
    input.value = ''; // Reset to allow re-selecting same file
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input.files?.length) return;

    const file = input.files[0];
    const reader = new FileReader();

    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (this.importMode === 'replace') {
             if (!this.editableReadme() || confirm('This will replace the current documentation. Continue?')) {
                 this.editableReadme.set(text);
             }
        } else {
             const current = this.editableReadme();
             this.editableReadme.set(current ? current + '\n\n' + text : text);
        }
    };
    reader.readAsText(file);
  }

  filteredRequirements = computed(() => {
    let reqs = this.dataService.requirements();
    const fId = this.dataService.selectedFeatureId();
    const sId = this.dataService.selectedSubsystemId();
    const sysId = this.dataService.selectedSystemId();

    // Context Filtering
    if (fId) reqs = reqs.filter(r => r.featureId === fId);
    else if (sId) reqs = reqs.filter(r => r.subsystemId === sId);
    else if (sysId) reqs = reqs.filter(r => r.systemId === sysId);

    // Search Filtering
    const term = this.searchTerm().toLowerCase();
    if (term) {
        reqs = reqs.filter(r => 
            r.title.toLowerCase().includes(term) || 
            r.description.toLowerCase().includes(term)
        );
    }

    return reqs;
  });

  canAddRequirement = computed(() => !!this.selectedFeature());

  openAddModal() {
    this.editingReqId.set(null);
    this.newReqTitle = '';
    this.newReqDesc = '';
    this.newReqPriority = 'Medium';
    this.showModal.set(true);
  }

  openEditModal(req: Requirement) {
    this.editingReqId.set(req.id);
    this.newReqTitle = req.title;
    this.newReqDesc = req.description;
    this.newReqPriority = req.priority;
    this.showModal.set(true);
  }

  openAiModal() {
    if (!this.aiEnabled()) {
        this.apiKeyInput = '';
        this.showApiKeyModal.set(true);
        return;
    }
    this.userStoryPrompt = '';
    this.showAiModal.set(true);
  }

  configureApiKey() {
    if (this.apiKeyInput.trim()) {
        const success = this.aiService.configure(this.apiKeyInput.trim());
        if (success) {
            this.showApiKeyModal.set(false);
            // Do not automatically open the AI generation modal
        } else {
            alert('Failed to configure AI service.');
        }
    }
  }

  async generateAiRequirements() {
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (!feat || !sub || !sys || !this.userStoryPrompt.trim()) return;

    this.isGenerating.set(true);
    const context = `System: ${sys.name}, Subsystem: ${sub.name}, Feature: ${feat.name}`;

    let docStack = '';
    if (sys.readme) docStack += `[SYSTEM DOCS]:\n${sys.readme}\n\n`;
    if (sub.readme) docStack += `[SUBSYSTEM DOCS]:\n${sub.readme}\n\n`;
    if (feat.readme) docStack += `[FEATURE DOCS]:\n${feat.readme}\n\n`;

    try {
      const generated = await this.aiService.generateRequirements(context, docStack, this.userStoryPrompt);

      generated.forEach(req => {
        this.dataService.addRequirement({
          title: req.title,
          description: req.description,
          priority: req.priority,
          status: 'Backlog',
          systemId: sys.id,
          subsystemId: sub.id,
          featureId: feat.id
        });
      });

      this.showAiModal.set(false);
    } finally {
      this.isGenerating.set(false);
    }
  }

  saveManual() {
    // Edit mode
    const editId = this.editingReqId();
    if (editId) {
        this.dataService.updateRequirement(editId, {
            title: this.newReqTitle,
            description: this.newReqDesc,
            priority: this.newReqPriority
        });
        this.showModal.set(false);
        return;
    }

    // Create mode
    const feat = this.selectedFeature();
    if (!feat) return;

    this.dataService.addRequirement({
      title: this.newReqTitle,
      description: this.newReqDesc,
      priority: this.newReqPriority,
      status: 'Backlog',
      systemId: this.dataService.selectedSystemId()!,
      subsystemId: this.dataService.selectedSubsystemId()!,
      featureId: feat.id
    });
    this.showModal.set(false);
  }

  // --- Export Logic ---

  toggleExportFilter() {
     this.includeInProgress.update(v => !v);
     // Re-generate context with new filter
     this.generateExportContext(this.includeInProgress());
  }

  copyPrompt(req?: Requirement) {
      if (req) {
          // Single Requirement Export
          this.generateExportContext(false, req);
          this.showExportModal.set(true);
      } else {
          // Scope Export (Default: ToDo only)
          this.includeInProgress.set(false);
          this.generateExportContext(false);
          this.showExportModal.set(true);
      }
  }

  generateExportContext(includeInProgress: boolean, singleReq?: Requirement) {
    const sys = this.selectedSystem();
    const sub = this.selectedSubsystem();
    const feat = this.selectedFeature();

    let content = 'PROJECT CONTEXT\n===============\n';
    if (sys) content += `System: ${sys.name}\nDescription: ${sys.description}\n\n`;
    if (sub) content += `Subsystem: ${sub.name}\nDescription: ${sub.description}\n\n`;
    if (feat) content += `Feature: ${feat.name}\nDescription: ${feat.description}\n\n`;

    content += 'DOCUMENTATION\n=============\n';
    if (sys?.readme) content += `[SYSTEM: ${sys.name}]\n${sys.readme}\n\n`;
    if (sub?.readme) content += `[SUBSYSTEM: ${sub.name}]\n${sub.readme}\n\n`;
    if (feat?.readme) content += `[FEATURE: ${feat.name}]\n${feat.readme}\n\n`;

    // Add Folders to Context if System
    if (sys?.folders && sys.folders.length > 0) {
        content += `\n[SYSTEM STRUCTURE]\n`;
        sys.folders.forEach(f => {
            content += `- ${f.name} [${f.category}]: ${f.note}\n`;
        });
        content += `\n`;
    }

    if (singleReq) {
      content += 'SELECTED REQUIREMENT\n====================\n';
      content += `Title: ${singleReq.title}\n`;
      content += `Status: ${singleReq.status}\n`;
      content += `Priority: ${singleReq.priority}\n`;
      content += `Description:\n${singleReq.description}\n`;

      content += '\nTASK\n====\n';
      content += `[Generate implementation steps, test cases, or code for: "${singleReq.title}"]\n`;

      this.exportParentId.set(singleReq.id);
      this.exportParentType.set('Requirement');
      this.exportParentName.set(singleReq.title);
      this.pendingExportReqIds.set([]); // No status update for single export? Or should we? Assuming no for now based on req.
    } else {
        // ROLL-UP REQUIREMENTS LOGIC
        const allReqs = this.dataService.requirements();
        let scopeReqs: Requirement[] = [];

        if (feat) {
            scopeReqs = allReqs.filter(r => r.featureId === feat.id);
        } else if (sub) {
            scopeReqs = allReqs.filter(r => r.subsystemId === sub.id);
        } else if (sys) {
            scopeReqs = allReqs.filter(r => r.systemId === sys.id);
        } else {
             scopeReqs = allReqs; 
        }

        // Apply Status Filter
        // Default: ToDo. With Toggle: ToDo + InProgress
        const allowedStatuses: Status[] = includeInProgress ? ['ToDo', 'InProgress'] : ['ToDo'];

        const filteredReqs = scopeReqs.filter(r => allowedStatuses.includes(r.status));
        this.pendingExportReqIds.set(filteredReqs.map(r => r.id));

        if (filteredReqs.length > 0) {
            content += 'SCOPE REQUIREMENTS\n==================\n';
            filteredReqs.forEach((r, index) => {
                content += `${index + 1}. [${r.status}] ${r.title} (Priority: ${r.priority})\n`;
                if (r.description) {
                    content += `   Details: ${r.description.replace(/\n/g, '\n   ')}\n`;
                }
                content += '\n';
            });
        }

        content += 'TASK\n====\n';
        content += '[Enter instruction here, e.g., Implement the requirements listed above, Generate test plan, etc.]\n';

        // Determine parent scope IDs for the session record
        if (feat) {
            this.exportParentId.set(feat.id);
            this.exportParentType.set('Feature');
            this.exportParentName.set(feat.name);
        } else if (sub) {
            this.exportParentId.set(sub.id);
            this.exportParentType.set('Subsystem');
            this.exportParentName.set(sub.name);
        } else if (sys) {
            this.exportParentId.set(sys.id);
            this.exportParentType.set('System');
            this.exportParentName.set(sys.name);
        }
    }

    this.exportContextText.set(content);
  }

  saveExportSession() {
      // 1. Save to DB
      this.dataService.addWorkSession({
          parentId: this.exportParentId(),
          parentType: this.exportParentType(),
          parentName: this.exportParentName(),
          context: this.exportContextText(),
          platform: this.exportPlatform(),
          model: this.exportModel(),
          status: 'Pending'
      });

      // 2. Copy to Clipboard
      navigator.clipboard.writeText(this.exportContextText()).then(() => {
          alert('Session Created! Context copied to clipboard.');
      }).catch(err => {
          console.error('Copy failed', err);
          alert('Session Created, but failed to copy text automatically.');
      });

      // 3. Update Requirements Status
      // "exporting context should move all associated requirements the In Progress status."
      if (this.pendingExportReqIds().length > 0) {
          this.dataService.batchUpdateRequirementStatus(this.pendingExportReqIds(), 'InProgress');
      }

      // 4. Close & Reset
      this.showExportModal.set(false);
  }
}

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // Global map of subsystem IDs to colors for easy lookup in views
  readonly subsystemColorMap = computed(() => {
    const map = new Map<string, string>();
    this.systems().forEach(sys => {
      sys.subsystems.forEach(sub => {
        if (sub.color) map.set(sub.id, sub.color);
      });
    });
    return map;
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  // Palette for subsystems
  private readonly colorPalette = [
    '#EF4444', // Red
    '#F97316', // Orange
    '#F59E0B', // Amber
    '#10B981', // Emerald
    '#06B6D4', // Cyan
    '#3B82F6', // Blue
    '#6366F1', // Indigo
    '#8B5CF6', // Violet
    '#EC4899', // Pink
    '#F43F5E', // Rose
    '#84CC16', // Lime
    '#14B8A6', // Teal
  ];

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getUniqueColor(systemId: string): string {
    const system = this.systems().find(s => s.id === systemId);
    if (!system) return this.colorPalette[0];

    const usedColors = new Set(system.subsystems.map(s => s.color));

    // Find first unused color
    const available = this.colorPalette.find(c => !usedColors.has(c));

    // Return available or random if all used
    return available || this.colorPalette[Math.floor(Math.random() * this.colorPalette.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    const color = this.getUniqueColor(systemId);

    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, input, output, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { Requirement, Status } from '../models/data.models';

@Component({
  selector: 'app-board-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './board-view.component.html'
})
export class BoardViewComponent {
  dataService = inject(DataService);
  requirements = input.required<Requirement[]>();
  copyReqPrompt = output<Requirement>();
  editReq = output<Requirement>();

  columns: Status[] = ['Backlog', 'ToDo', 'InProgress', 'Done'];
  draggedReqId: string | null = null;

  subsystemColors = computed(() => this.dataService.subsystemColorMap());

  getRequirementsByStatus(status: Status) {
    return this.requirements().filter(r => r.status === status);
  }

  formatStatus(status: string) {
    return status.replace(/([A-Z])/g, ' $1').trim();
  }

  getPriorityColor(priority: string) {
    switch(priority) {
      case 'High': return 'bg-red-500';
      case 'Medium': return 'bg-yellow-500';
      case 'Low': return 'bg-blue-400';
      default: return 'bg-gray-300';
    }
  }

  deleteReq(id: string, event: Event) {
    event.stopPropagation();
    if(confirm('Delete requirement?')) {
      this.dataService.deleteRequirement(id);
    }
  }

  onCopy(req: Requirement, event: Event) {
    event.stopPropagation();
    this.copyReqPrompt.emit(req);
  }

  onEdit(req: Requirement, event: Event) {
      event.stopPropagation();
      this.editReq.emit(req);
  }

  // --- Drag and Drop Logic ---
  onDragStart(event: DragEvent, id: string) {
    this.draggedReqId = id;
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', id);
    }
  }

  onDragOver(event: DragEvent) {
    event.preventDefault(); 
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = 'move';
    }
  }

  onDrop(event: DragEvent, newStatus: Status) {
    event.preventDefault();
    const id = this.draggedReqId;
    if (id) {
      this.dataService.updateRequirementStatus(id, newStatus);
    }
    this.draggedReqId = null;
  }

  moveStatus(req: Requirement, direction: number) {
     const idx = this.columns.indexOf(req.status);
     const newIdx = idx + direction;
     if (newIdx >= 0 && newIdx < this.columns.length) {
        this.dataService.updateRequirementStatus(req.id, this.columns[newIdx]);
     }
  }
}

import { Component, input, output, signal, computed, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { Requirement, Status } from '../models/data.models';

@Component({
  selector: 'app-table-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './table-view.component.html'
})
export class TableViewComponent {
  dataService = inject(DataService);
  requirements = input.required<Requirement[]>();
  editReq = output<Requirement>();
  copyReqPrompt = output<Requirement>();

  sortField = signal<keyof Requirement | 'date'>('date');
  sortDirection = signal<'asc' | 'desc'>('desc');

  subsystemColors = computed(() => this.dataService.subsystemColorMap());

  sortedRequirements = computed(() => {
    const reqs = [...this.requirements()];
    const field = this.sortField();
    const dir = this.sortDirection();

    return reqs.sort((a, b) => {
      let valA: any = a[field as keyof Requirement];
      let valB: any = b[field as keyof Requirement];

      if (field === 'date') {
        valA = a.createdAt;
        valB = b.createdAt;
      }

      if (valA < valB) return dir === 'asc' ? -1 : 1;
      if (valA > valB) return dir === 'asc' ? 1 : -1;
      return 0;
    });
  });

  toggleSort(field: keyof Requirement | 'date') {
    if (this.sortField() === field) {
      this.sortDirection.update(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      this.sortField.set(field);
      this.sortDirection.set('desc'); // Default to desc for new columns usually better for dates/importance
    }
  }

  getPriorityClass(priority: string) {
    switch(priority) {
      case 'High': return 'bg-red-100 text-red-800';
      case 'Medium': return 'bg-yellow-100 text-yellow-800';
      case 'Low': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  }

  getStatusClass(status: string) {
     switch(status) {
      case 'Done': return 'bg-green-100 text-green-800';
      case 'InProgress': return 'bg-blue-100 text-blue-800';
      case 'ToDo': return 'bg-gray-100 text-gray-800';
      case 'Backlog': return 'bg-purple-100 text-purple-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  }

  onEdit(req: Requirement, event: Event) {
    event.stopPropagation();
    this.editReq.emit(req);
  }

  onCopy(req: Requirement, event: Event) {
    event.stopPropagation();
    this.copyReqPrompt.emit(req);
  }

  deleteReq(id: string, event: Event) {
    event.stopPropagation();
    if(confirm('Are you sure you want to delete this requirement?')) {
      this.dataService.deleteRequirement(id);
    }
  }
}

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // Global map of subsystem IDs to colors for easy lookup in views
  readonly subsystemColorMap = computed(() => {
    const map = new Map<string, string>();
    this.systems().forEach(sys => {
      sys.subsystems.forEach(sub => {
        if (sub.color) map.set(sub.id, sub.color);
      });
    });
    return map;
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  // Palette for subsystems
  private readonly colorPalette = [
    '#EF4444', // Red
    '#F97316', // Orange
    '#F59E0B', // Amber
    '#10B981', // Emerald
    '#06B6D4', // Cyan
    '#3B82F6', // Blue
    '#6366F1', // Indigo
    '#8B5CF6', // Violet
    '#EC4899', // Pink
    '#F43F5E', // Rose
    '#84CC16', // Lime
    '#14B8A6', // Teal
  ];

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getUniqueColor(systemId: string): string {
    const system = this.systems().find(s => s.id === systemId);
    if (!system) return this.colorPalette[0];

    const usedColors = new Set(system.subsystems.map(s => s.color));

    // Find first unused color
    const available = this.colorPalette.find(c => !usedColors.has(c));

    // Return available or random if all used
    return available || this.colorPalette[Math.floor(Math.random() * this.colorPalette.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    const color = this.getUniqueColor(systemId);

    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Rearrange / Move Logic ---

  moveFeature(featureId: string, targetSystemId: string, targetSubsystemId: string) {
    // 1. Find the feature and remove from old location
    let feature: Feature | undefined;
    this.systems.update(systems => systems.map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => {
        const found = sub.features.find(f => f.id === featureId);
        if (found) {
            feature = found;
            return { ...sub, features: sub.features.filter(f => f.id !== featureId) };
        }
        return sub;
      })
    })));

    if (!feature) return;

    // 2. Add to new location
    feature.subsystemId = targetSubsystemId;
    this.systems.update(systems => systems.map(sys => {
        if (sys.id === targetSystemId) {
            return {
                ...sys,
                subsystems: sys.subsystems.map(sub => {
                    if (sub.id === targetSubsystemId) {
                        return { ...sub, features: [...sub.features, feature!] };
                    }
                    return sub;
                })
            }
        }
        return sys;
    }));

    // 3. Update Requirements
    this.requirements.update(reqs => reqs.map(r => {
        if (r.featureId === featureId) {
            return { ...r, systemId: targetSystemId, subsystemId: targetSubsystemId };
        }
        return r;
    }));
  }

  moveSubsystem(subsystemId: string, targetSystemId: string) {
     let subsystem: Subsystem | undefined;

     // 1. Find and remove from old system
     this.systems.update(systems => systems.map(sys => {
         const found = sys.subsystems.find(s => s.id === subsystemId);
         if (found) {
             subsystem = found;
             return { ...sys, subsystems: sys.subsystems.filter(s => s.id !== subsystemId) };
         }
         return sys;
     }));

     if (!subsystem) return;

     // 2. Add to new system
     subsystem.systemId = targetSystemId;
     this.systems.update(systems => systems.map(sys => {
         if (sys.id === targetSystemId) {
             return { ...sys, subsystems: [...sys.subsystems, subsystem!] };
         }
         return sys;
     }));

     // 3. Update Requirements
     this.requirements.update(reqs => reqs.map(r => {
         if (r.subsystemId === subsystemId) {
             return { ...r, systemId: targetSystemId };
         }
         return r;
     }));
  }

  // Demote a System to become a Subsystem of another System
  demoteSystem(sourceSystemId: string, targetSystemId: string) {
      const allSystems = this.systems();
      const sourceSystem = allSystems.find(s => s.id === sourceSystemId);
      const targetSystem = allSystems.find(s => s.id === targetSystemId);

      if (!sourceSystem || !targetSystem) return;

      // 1. Create a new Subsystem in Target based on Source System
      const newSubsystemId = crypto.randomUUID();
      const newSubsystem: Subsystem = {
          id: newSubsystemId,
          name: sourceSystem.name,
          description: sourceSystem.description,
          readme: sourceSystem.readme,
          color: this.getUniqueColor(targetSystemId),
          systemId: targetSystemId,
          features: []
      };

      // 2. Convert Source Subsystems into Features for the new Subsystem
      sourceSystem.subsystems.forEach(oldSub => {
          const newFeature: Feature = {
              id: crypto.randomUUID(), // New ID to be safe, or keep old? Keeping old might break references if types mix. Let's keep ID to save req references where possible, but Feature schema != Subsystem schema.
              // Actually, simpler to keep ID if we are careful, BUT 'Subsystem' has features, 'Feature' doesn't.
              // We must Flatten.
              name: oldSub.name,
              description: oldSub.description,
              readme: oldSub.readme,
              subsystemId: newSubsystemId
          };

          // Add this "Converted Feature" to the new Subsystem
          newSubsystem.features.push(newFeature);

          // Update Requirements linked to the OLD Subsystem to point to the NEW Feature
          // And also update their System ID.
          // OLD: systemId=source, subsystemId=oldSub.id, featureId=null
          // NEW: systemId=target, subsystemId=newSubsystemId, featureId=newFeature.id
          this.requirements.update(reqs => reqs.map(r => {
              if (r.subsystemId === oldSub.id) {
                  return { 
                      ...r, 
                      systemId: targetSystemId, 
                      subsystemId: newSubsystemId, 
                      featureId: newFeature.id // Link reqs that were at subsystem level to this new feature
                  };
              }
              return r;
          }));

          // What about reqs that were inside Features of the old Subsystem?
          // They need to be moved to the new Feature as well (Flattened) because Features can't have Features.
          // OLD: featureId IN oldSub.features
          const oldFeatureIds = oldSub.features.map(f => f.id);
          this.requirements.update(reqs => reqs.map(r => {
              if (oldFeatureIds.includes(r.featureId)) {
                   return {
                       ...r,
                       systemId: targetSystemId,
                       subsystemId: newSubsystemId,
                       featureId: newFeature.id // Flattened into the converted feature
                   };
              }
              return r;
          }));
      });

      // 3. Handle Direct Requirements of the Source System (no subsystem)
      // They move to the new Subsystem (no feature)
      this.requirements.update(reqs => reqs.map(r => {
          if (r.systemId === sourceSystemId && !r.subsystemId) {
              return {
                  ...r,
                  systemId: targetSystemId,
                  subsystemId: newSubsystemId
              };
          }
          return r;
      }));

      // 4. Add the new Subsystem to the Target System state
      this.systems.update(systems => systems.map(sys => {
          if (sys.id === targetSystemId) {
              return { ...sys, subsystems: [...sys.subsystems, newSubsystem] };
          }
          return sys;
      }));

      // 5. Delete the old Source System
      // (This automatically filters out the old system from the array)
      this.systems.update(sys => sys.filter(s => s.id !== sourceSystemId));

      // 6. Reset Selection
      this.selectedSystemId.set(targetSystemId);
      this.selectedSubsystemId.set(newSubsystemId);
      this.selectedFeatureId.set(null);
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';
import { System, Subsystem, Feature } from '../models/data.models';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  // --- Move/Reparent Modal State ---
  showMoveModal = signal(false);
  moveTargetType = signal<'System' | 'Subsystem' | 'Feature'>('System'); // What we are moving
  movingItemId = signal<string | null>(null);
  movingItemName = signal<string>('');

  // For Feature Move:
  targetSystemIdForFeature = signal<string>('');

  // Selection
  selectedMoveTargetId = signal<string>('');

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }

  // --- Move Logic ---

  initiateMove(type: 'System' | 'Subsystem' | 'Feature', item: System | Subsystem | Feature, event: Event) {
      event.stopPropagation();
      this.moveTargetType.set(type);
      this.movingItemId.set(item.id);
      this.movingItemName.set(item.name);
      this.selectedMoveTargetId.set('');
      this.showMoveModal.set(true);

      // Pre-select first valid target if possible
      if (type === 'System' || type === 'Subsystem') {
          const firstSys = this.dataService.systems().find(s => s.id !== item.id); // Exclude self
          if (firstSys) this.selectedMoveTargetId.set(firstSys.id);
      } else if (type === 'Feature') {
          // Default to current system for feature move context
          const currentSysId = this.dataService.selectedSystemId();
          if (currentSysId) this.targetSystemIdForFeature.set(currentSysId);
      }
  }

  executeMove() {
      const type = this.moveTargetType();
      const itemId = this.movingItemId();
      const targetId = this.selectedMoveTargetId();

      if (!itemId || !targetId) return;

      if (type === 'System') {
          // Demote System -> Subsystem
          if (confirm(`Convert System "${this.movingItemName()}" into a Subsystem of the selected target? This will restructure its contents.`)) {
              this.dataService.demoteSystem(itemId, targetId);
          }
      } else if (type === 'Subsystem') {
          // Move Subsystem -> New System
          this.dataService.moveSubsystem(itemId, targetId);
      } else if (type === 'Feature') {
          // Move Feature -> New Subsystem
          const sysId = this.targetSystemIdForFeature(); // System of the target subsystem
          if (sysId) {
             this.dataService.moveFeature(itemId, sysId, targetId);
          }
      }

      this.showMoveModal.set(false);
  }

  // Helper for Feature move modal: Filter subsystems based on selected System
  availableSubsystemsForFeature = computed(() => {
      if (this.moveTargetType() !== 'Feature') return [];
      const sysId = this.targetSystemIdForFeature();
      if (!sysId) return [];
      const sys = this.dataService.systems().find(s => s.id === sysId);
      return sys ? sys.subsystems : [];
  });

  // Helper for System/Subsystem move: List of Systems
  availableSystems = computed(() => {
      const type = this.moveTargetType();
      const movingId = this.movingItemId();
      // Exclude self if moving a system
      if (type === 'System') {
          return this.dataService.systems().filter(s => s.id !== movingId);
      }
      return this.dataService.systems();
  });
}

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // Global map of subsystem IDs to colors for easy lookup in views
  readonly subsystemColorMap = computed(() => {
    const map = new Map<string, string>();
    this.systems().forEach(sys => {
      sys.subsystems.forEach(sub => {
        if (sub.color) map.set(sub.id, sub.color);
      });
    });
    return map;
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  // Palette for subsystems
  private readonly colorPalette = [
    '#EF4444', // Red
    '#F97316', // Orange
    '#F59E0B', // Amber
    '#10B981', // Emerald
    '#06B6D4', // Cyan
    '#3B82F6', // Blue
    '#6366F1', // Indigo
    '#8B5CF6', // Violet
    '#EC4899', // Pink
    '#F43F5E', // Rose
    '#84CC16', // Lime
    '#14B8A6', // Teal
  ];

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getUniqueColor(systemId: string): string {
    const system = this.systems().find(s => s.id === systemId);
    if (!system) return this.colorPalette[0];

    const usedColors = new Set(system.subsystems.map(s => s.color));

    // Find first unused color
    const available = this.colorPalette.find(c => !usedColors.has(c));

    // Return available or random if all used
    return available || this.colorPalette[Math.floor(Math.random() * this.colorPalette.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Import / Export ---
  exportDatabase() {
    const data = {
      systems: this.systems(),
      requirements: this.requirements(),
      workSessions: this.workSessions(),
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      }
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nebula-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    window.URL.revokeObjectURL(url);
  }

  importDatabase(file: File) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (json.systems && Array.isArray(json.systems)) {
          this.systems.set(json.systems);
        }
        if (json.requirements && Array.isArray(json.requirements)) {
          this.requirements.set(json.requirements);
        }
        if (json.workSessions && Array.isArray(json.workSessions)) {
          this.workSessions.set(json.workSessions);
        }
        alert('Database restored successfully!');
      } catch (err) {
        console.error(err);
        alert('Failed to parse backup file.');
      }
    };
    reader.readAsText(file);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    const color = this.getUniqueColor(systemId);

    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Rearrange / Move Logic ---

  moveFeature(featureId: string, targetSystemId: string, targetSubsystemId: string) {
    // 1. Find the feature and remove from old location
    let feature: Feature | undefined;
    this.systems.update(systems => systems.map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => {
        const found = sub.features.find(f => f.id === featureId);
        if (found) {
            feature = found;
            return { ...sub, features: sub.features.filter(f => f.id !== featureId) };
        }
        return sub;
      })
    })));

    if (!feature) return;

    // 2. Add to new location
    feature.subsystemId = targetSubsystemId;
    this.systems.update(systems => systems.map(sys => {
        if (sys.id === targetSystemId) {
            return {
                ...sys,
                subsystems: sys.subsystems.map(sub => {
                    if (sub.id === targetSubsystemId) {
                        return { ...sub, features: [...sub.features, feature!] };
                    }
                    return sub;
                })
            }
        }
        return sys;
    }));

    // 3. Update Requirements
    this.requirements.update(reqs => reqs.map(r => {
        if (r.featureId === featureId) {
            return { ...r, systemId: targetSystemId, subsystemId: targetSubsystemId };
        }
        return r;
    }));
  }

  moveSubsystem(subsystemId: string, targetSystemId: string) {
     let subsystem: Subsystem | undefined;

     // 1. Find and remove from old system
     this.systems.update(systems => systems.map(sys => {
         const found = sys.subsystems.find(s => s.id === subsystemId);
         if (found) {
             subsystem = found;
             return { ...sys, subsystems: sys.subsystems.filter(s => s.id !== subsystemId) };
         }
         return sys;
     }));

     if (!subsystem) return;

     // 2. Add to new system
     subsystem.systemId = targetSystemId;
     this.systems.update(systems => systems.map(sys => {
         if (sys.id === targetSystemId) {
             return { ...sys, subsystems: [...sys.subsystems, subsystem!] };
         }
         return sys;
     }));

     // 3. Update Requirements
     this.requirements.update(reqs => reqs.map(r => {
         if (r.subsystemId === subsystemId) {
             return { ...r, systemId: targetSystemId };
         }
         return r;
     }));
  }

  // Demote a System to become a Subsystem of another System
  demoteSystem(sourceSystemId: string, targetSystemId: string) {
      const allSystems = this.systems();
      const sourceSystem = allSystems.find(s => s.id === sourceSystemId);
      const targetSystem = allSystems.find(s => s.id === targetSystemId);

      if (!sourceSystem || !targetSystem) return;

      // 1. Create a new Subsystem in Target based on Source System
      const newSubsystemId = crypto.randomUUID();
      const newSubsystem: Subsystem = {
          id: newSubsystemId,
          name: sourceSystem.name,
          description: sourceSystem.description,
          readme: sourceSystem.readme,
          color: this.getUniqueColor(targetSystemId),
          systemId: targetSystemId,
          features: []
      };

      // 2. Convert Source Subsystems into Features for the new Subsystem
      sourceSystem.subsystems.forEach(oldSub => {
          const newFeature: Feature = {
              id: crypto.randomUUID(), // New ID to be safe, or keep old? Keeping old might break references if types mix. Let's keep ID to save req references where possible, but Feature schema != Subsystem schema.
              // Actually, simpler to keep ID if we are careful, BUT 'Subsystem' has features, 'Feature' doesn't.
              // We must Flatten.
              name: oldSub.name,
              description: oldSub.description,
              readme: oldSub.readme,
              subsystemId: newSubsystemId
          };

          // Add this "Converted Feature" to the new Subsystem
          newSubsystem.features.push(newFeature);

          // Update Requirements linked to the OLD Subsystem to point to the NEW Feature
          // And also update their System ID.
          // OLD: systemId=source, subsystemId=oldSub.id, featureId=null
          // NEW: systemId=target, subsystemId=newSubsystemId, featureId=newFeature.id
          this.requirements.update(reqs => reqs.map(r => {
              if (r.subsystemId === oldSub.id) {
                  return { 
                      ...r, 
                      systemId: targetSystemId, 
                      subsystemId: newSubsystemId, 
                      featureId: newFeature.id // Link reqs that were at subsystem level to this new feature
                  };
              }
              return r;
          }));

          // What about reqs that were inside Features of the old Subsystem?
          // They need to be moved to the new Feature as well (Flattened) because Features can't have Features.
          // OLD: featureId IN oldSub.features
          const oldFeatureIds = oldSub.features.map(f => f.id);
          this.requirements.update(reqs => reqs.map(r => {
              if (oldFeatureIds.includes(r.featureId)) {
                   return {
                       ...r,
                       systemId: targetSystemId,
                       subsystemId: newSubsystemId,
                       featureId: newFeature.id // Flattened into the converted feature
                   };
              }
              return r;
          }));
      });

      // 3. Handle Direct Requirements of the Source System (no subsystem)
      // They move to the new Subsystem (no feature)
      this.requirements.update(reqs => reqs.map(r => {
          if (r.systemId === sourceSystemId && !r.subsystemId) {
              return {
                  ...r,
                  systemId: targetSystemId,
                  subsystemId: newSubsystemId
              };
          }
          return r;
      }));

      // 4. Add the new Subsystem to the Target System state
      this.systems.update(systems => systems.map(sys => {
          if (sys.id === targetSystemId) {
              return { ...sys, subsystems: [...sys.subsystems, newSubsystem] };
          }
          return sys;
      }));

      // 5. Delete the old Source System
      // (This automatically filters out the old system from the array)
      this.systems.update(sys => sys.filter(s => s.id !== sourceSystemId));

      // 6. Reset Selection
      this.selectedSystemId.set(targetSystemId);
      this.selectedSubsystemId.set(newSubsystemId);
      this.selectedFeatureId.set(null);
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';
import { System, Subsystem, Feature } from '../models/data.models';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  // --- Move/Reparent Modal State ---
  showMoveModal = signal(false);
  moveTargetType = signal<'System' | 'Subsystem' | 'Feature'>('System'); // What we are moving
  movingItemId = signal<string | null>(null);
  movingItemName = signal<string>('');

  // For Feature Move:
  targetSystemIdForFeature = signal<string>('');

  // Selection
  selectedMoveTargetId = signal<string>('');

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  // --- Import / Export ---
  triggerExport() {
    this.dataService.exportDatabase();
  }

  triggerImport(input: HTMLInputElement) {
    input.value = '';
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      this.dataService.importDatabase(input.files[0]);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }

  // --- Move Logic ---

  initiateMove(type: 'System' | 'Subsystem' | 'Feature', item: System | Subsystem | Feature, event: Event) {
      event.stopPropagation();
      this.moveTargetType.set(type);
      this.movingItemId.set(item.id);
      this.movingItemName.set(item.name);
      this.selectedMoveTargetId.set('');
      this.showMoveModal.set(true);

      // Pre-select first valid target if possible
      if (type === 'System' || type === 'Subsystem') {
          const firstSys = this.dataService.systems().find(s => s.id !== item.id); // Exclude self
          if (firstSys) this.selectedMoveTargetId.set(firstSys.id);
      } else if (type === 'Feature') {
          // Default to current system for feature move context
          const currentSysId = this.dataService.selectedSystemId();
          if (currentSysId) this.targetSystemIdForFeature.set(currentSysId);
      }
  }

  executeMove() {
      const type = this.moveTargetType();
      const itemId = this.movingItemId();
      const targetId = this.selectedMoveTargetId();

      if (!itemId || !targetId) return;

      if (type === 'System') {
          // Demote System -> Subsystem
          if (confirm(`Convert System "${this.movingItemName()}" into a Subsystem of the selected target? This will restructure its contents.`)) {
              this.dataService.demoteSystem(itemId, targetId);
          }
      } else if (type === 'Subsystem') {
          // Move Subsystem -> New System
          this.dataService.moveSubsystem(itemId, targetId);
      } else if (type === 'Feature') {
          // Move Feature -> New Subsystem
          const sysId = this.targetSystemIdForFeature(); // System of the target subsystem
          if (sysId) {
             this.dataService.moveFeature(itemId, sysId, targetId);
          }
      }

      this.showMoveModal.set(false);
  }

  // Helper for Feature move modal: Filter subsystems based on selected System
  availableSubsystemsForFeature = computed(() => {
      if (this.moveTargetType() !== 'Feature') return [];
      const sysId = this.targetSystemIdForFeature();
      if (!sysId) return [];
      const sys = this.dataService.systems().find(s => s.id === sysId);
      return sys ? sys.subsystems : [];
  });

  // Helper for System/Subsystem move: List of Systems
  availableSystems = computed(() => {
      const type = this.moveTargetType();
      const movingId = this.movingItemId();
      // Exclude self if moving a system
      if (type === 'System') {
          return this.dataService.systems().filter(s => s.id !== movingId);
      }
      return this.dataService.systems();
  });
}

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

// Normalized Schema Suggestion
// Flatten the nested array structure to make updates atomic and efficient.
export default defineSchema({
  // Systems (Top Level)
  systems: defineTable({
    name: v.string(),
    description: v.string(),
    readme: v.optional(v.string()),
    createdAt: v.number(),
  }),

  // Subsystems (Child of System)
  subsystems: defineTable({
    systemId: v.id("systems"),
    name: v.string(),
    description: v.string(),
    readme: v.optional(v.string()),
    color: v.string(), // Hex code
    createdAt: v.number(),
  }).index("by_system", ["systemId"]),

  // Features (Child of Subsystem)
  features: defineTable({
    subsystemId: v.id("subsystems"),
    name: v.string(),
    description: v.string(),
    readme: v.optional(v.string()),
    createdAt: v.number(),
  }).index("by_subsystem", ["subsystemId"]),

  // Requirements (Child of Feature OR System/Subsystem if flexible)
  requirements: defineTable({
    systemId: v.id("systems"),       // Denormalized for easy filtering
    subsystemId: v.id("subsystems"), // Denormalized
    featureId: v.optional(v.id("features")), 

    title: v.string(),
    description: v.string(),
    status: v.string(), // 'Backlog' | 'ToDo' | 'InProgress' | 'Done'
    priority: v.string(), // 'Low' | 'Medium' | 'High'
    createdAt: v.number(),
    updatedAt: v.number(),
  })
  .index("by_system", ["systemId"])
  .index("by_subsystem", ["subsystemId"])
  .index("by_feature", ["featureId"]),

  // Work Sessions (AI History)
  workSessions: defineTable({
    parentId: v.string(), // Can be ID of system/subsystem/feature
    parentType: v.string(),
    parentName: v.string(),
    context: v.string(),
    platform: v.string(),
    model: v.string(),
    outcome: v.optional(v.string()),
    status: v.string(),
    createdAt: v.number(),
    updatedAt: v.number(),
  }),
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";

// --- Queries (Get Data) ---

export const getFullBoard = query({
  args: {},
  handler: async (ctx) => {
    // In a real app, you might query these individually per component
    // But for a full sync, fetching all is okay for small-medium projects.
    const systems = await ctx.db.query("systems").collect();
    const subsystems = await ctx.db.query("subsystems").collect();
    const features = await ctx.db.query("features").collect();
    const requirements = await ctx.db.query("requirements").collect();

    return { systems, subsystems, features, requirements };
  },
});

// --- Mutations (Modify Data) ---

export const createSystem = mutation({
  args: { name: v.string(), description: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db.insert("systems", {
      name: args.name,
      description: args.description,
      createdAt: Date.now(),
    });
  },
});

export const createSubsystem = mutation({
  args: { systemId: v.id("systems"), name: v.string(), description: v.string(), color: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db.insert("subsystems", {
      systemId: args.systemId,
      name: args.name,
      description: args.description,
      color: args.color,
      createdAt: Date.now(),
    });
  },
});

export const moveSubsystem = mutation({
  args: { subsystemId: v.id("subsystems"), targetSystemId: v.id("systems") },
  handler: async (ctx, args) => {
    // Atomic update of parent reference
    await ctx.db.patch(args.subsystemId, { systemId: args.targetSystemId });

    // Also update requirements associated with this subsystem
    const reqs = await ctx.db
      .query("requirements")
      .withIndex("by_subsystem", (q) => q.eq("subsystemId", args.subsystemId))
      .collect();

    for (const req of reqs) {
        await ctx.db.patch(req._id, { systemId: args.targetSystemId });
    }
  },
});

export const updateRequirementStatus = mutation({
  args: { requirementId: v.id("requirements"), status: v.string() },
  handler: async (ctx, args) => {
    await ctx.db.patch(args.requirementId, { 
        status: args.status, 
        updatedAt: Date.now() 
    });
  },
});

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // Global map of subsystem IDs to colors for easy lookup in views
  readonly subsystemColorMap = computed(() => {
    const map = new Map<string, string>();
    this.systems().forEach(sys => {
      sys.subsystems.forEach(sub => {
        if (sub.color) map.set(sub.id, sub.color);
      });
    });
    return map;
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);
  readonly viewMode = signal<'board' | 'table' | 'docs' | 'sessions'>('board');

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  // Palette for subsystems
  private readonly colorPalette = [
    '#EF4444', // Red
    '#F97316', // Orange
    '#F59E0B', // Amber
    '#10B981', // Emerald
    '#06B6D4', // Cyan
    '#3B82F6', // Blue
    '#6366F1', // Indigo
    '#8B5CF6', // Violet
    '#EC4899', // Pink
    '#F43F5E', // Rose
    '#84CC16', // Lime
    '#14B8A6', // Teal
  ];

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getUniqueColor(systemId: string): string {
    const system = this.systems().find(s => s.id === systemId);
    if (!system) return this.colorPalette[0];

    const usedColors = new Set(system.subsystems.map(s => s.color));

    // Find first unused color
    const available = this.colorPalette.find(c => !usedColors.has(c));

    // Return available or random if all used
    return available || this.colorPalette[Math.floor(Math.random() * this.colorPalette.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Import / Export ---
  exportDatabase() {
    const data = {
      systems: this.systems(),
      requirements: this.requirements(),
      workSessions: this.workSessions(),
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      }
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nebula-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    window.URL.revokeObjectURL(url);
  }

  importDatabase(file: File) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (json.systems && Array.isArray(json.systems)) {
          this.systems.set(json.systems);
        }
        if (json.requirements && Array.isArray(json.requirements)) {
          this.requirements.set(json.requirements);
        }
        if (json.workSessions && Array.isArray(json.workSessions)) {
          this.workSessions.set(json.workSessions);
        }
        alert('Database restored successfully!');
      } catch (err) {
        console.error(err);
        alert('Failed to parse backup file.');
      }
    };
    reader.readAsText(file);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    const color = this.getUniqueColor(systemId);

    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Rearrange / Move Logic ---

  moveFeature(featureId: string, targetSystemId: string, targetSubsystemId: string) {
    // 1. Find the feature and remove from old location
    let feature: Feature | undefined;
    this.systems.update(systems => systems.map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => {
        const found = sub.features.find(f => f.id === featureId);
        if (found) {
            feature = found;
            return { ...sub, features: sub.features.filter(f => f.id !== featureId) };
        }
        return sub;
      })
    })));

    if (!feature) return;

    // 2. Add to new location
    feature.subsystemId = targetSubsystemId;
    this.systems.update(systems => systems.map(sys => {
        if (sys.id === targetSystemId) {
            return {
                ...sys,
                subsystems: sys.subsystems.map(sub => {
                    if (sub.id === targetSubsystemId) {
                        return { ...sub, features: [...sub.features, feature!] };
                    }
                    return sub;
                })
            }
        }
        return sys;
    }));

    // 3. Update Requirements
    this.requirements.update(reqs => reqs.map(r => {
        if (r.featureId === featureId) {
            return { ...r, systemId: targetSystemId, subsystemId: targetSubsystemId };
        }
        return r;
    }));
  }

  moveSubsystem(subsystemId: string, targetSystemId: string) {
     let subsystem: Subsystem | undefined;

     // 1. Find and remove from old system
     this.systems.update(systems => systems.map(sys => {
         const found = sys.subsystems.find(s => s.id === subsystemId);
         if (found) {
             subsystem = found;
             return { ...sys, subsystems: sys.subsystems.filter(s => s.id !== subsystemId) };
         }
         return sys;
     }));

     if (!subsystem) return;

     // 2. Add to new system
     subsystem.systemId = targetSystemId;
     this.systems.update(systems => systems.map(sys => {
         if (sys.id === targetSystemId) {
             return { ...sys, subsystems: [...sys.subsystems, subsystem!] };
         }
         return sys;
     }));

     // 3. Update Requirements
     this.requirements.update(reqs => reqs.map(r => {
         if (r.subsystemId === subsystemId) {
             return { ...r, systemId: targetSystemId };
         }
         return r;
     }));
  }

  // Demote a System to become a Subsystem of another System
  demoteSystem(sourceSystemId: string, targetSystemId: string) {
      const allSystems = this.systems();
      const sourceSystem = allSystems.find(s => s.id === sourceSystemId);
      const targetSystem = allSystems.find(s => s.id === targetSystemId);

      if (!sourceSystem || !targetSystem) return;

      // 1. Create a new Subsystem in Target based on Source System
      const newSubsystemId = crypto.randomUUID();
      const newSubsystem: Subsystem = {
          id: newSubsystemId,
          name: sourceSystem.name,
          description: sourceSystem.description,
          readme: sourceSystem.readme,
          color: this.getUniqueColor(targetSystemId),
          systemId: targetSystemId,
          features: []
      };

      // 2. Convert Source Subsystems into Features for the new Subsystem
      sourceSystem.subsystems.forEach(oldSub => {
          const newFeature: Feature = {
              id: crypto.randomUUID(), // New ID to be safe, or keep old? Keeping old might break references if types mix. Let's keep ID to save req references where possible, but Feature schema != Subsystem schema.
              // Actually, simpler to keep ID if we are careful, BUT 'Subsystem' has features, 'Feature' doesn't.
              // We must Flatten.
              name: oldSub.name,
              description: oldSub.description,
              readme: oldSub.readme,
              subsystemId: newSubsystemId
          };

          // Add this "Converted Feature" to the new Subsystem
          newSubsystem.features.push(newFeature);

          // Update Requirements linked to the OLD Subsystem to point to the NEW Feature
          // And also update their System ID.
          // OLD: systemId=source, subsystemId=oldSub.id, featureId=null
          // NEW: systemId=target, subsystemId=newSubsystemId, featureId=newFeature.id
          this.requirements.update(reqs => reqs.map(r => {
              if (r.subsystemId === oldSub.id) {
                  return { 
                      ...r, 
                      systemId: targetSystemId, 
                      subsystemId: newSubsystemId, 
                      featureId: newFeature.id // Link reqs that were at subsystem level to this new feature
                  };
              }
              return r;
          }));

          // What about reqs that were inside Features of the old Subsystem?
          // They need to be moved to the new Feature as well (Flattened) because Features can't have Features.
          // OLD: featureId IN oldSub.features
          const oldFeatureIds = oldSub.features.map(f => f.id);
          this.requirements.update(reqs => reqs.map(r => {
              if (oldFeatureIds.includes(r.featureId)) {
                   return {
                       ...r,
                       systemId: targetSystemId,
                       subsystemId: newSubsystemId,
                       featureId: newFeature.id // Flattened into the converted feature
                   };
              }
              return r;
          }));
      });

      // 3. Handle Direct Requirements of the Source System (no subsystem)
      // They move to the new Subsystem (no feature)
      this.requirements.update(reqs => reqs.map(r => {
          if (r.systemId === sourceSystemId && !r.subsystemId) {
              return {
                  ...r,
                  systemId: targetSystemId,
                  subsystemId: newSubsystemId
              };
          }
          return r;
      }));

      // 4. Add the new Subsystem to the Target System state
      this.systems.update(systems => systems.map(sys => {
          if (sys.id === targetSystemId) {
              return { ...sys, subsystems: [...sys.subsystems, newSubsystem] };
          }
          return sys;
      }));

      // 5. Delete the old Source System
      // (This automatically filters out the old system from the array)
      this.systems.update(sys => sys.filter(s => s.id !== sourceSystemId));

      // 6. Reset Selection
      this.selectedSystemId.set(targetSystemId);
      this.selectedSubsystemId.set(newSubsystemId);
      this.selectedFeatureId.set(null);
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';
import { System, Subsystem, Feature } from '../models/data.models';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  // --- Move/Reparent Modal State ---
  showMoveModal = signal(false);
  moveTargetType = signal<'System' | 'Subsystem' | 'Feature'>('System'); // What we are moving
  movingItemId = signal<string | null>(null);
  movingItemName = signal<string>('');

  // For Feature Move:
  targetSystemIdForFeature = signal<string>('');

  // Selection
  selectedMoveTargetId = signal<string>('');

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  // --- Import / Export ---
  triggerExport() {
    this.dataService.exportDatabase();
  }

  triggerImport(input: HTMLInputElement) {
    input.value = '';
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      this.dataService.importDatabase(input.files[0]);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }

  // --- Move Logic ---

  initiateMove(type: 'System' | 'Subsystem' | 'Feature', item: System | Subsystem | Feature, event: Event) {
      event.stopPropagation();
      this.moveTargetType.set(type);
      this.movingItemId.set(item.id);
      this.movingItemName.set(item.name);
      this.selectedMoveTargetId.set('');
      this.showMoveModal.set(true);

      // Pre-select first valid target if possible
      if (type === 'System' || type === 'Subsystem') {
          const firstSys = this.dataService.systems().find(s => s.id !== item.id); // Exclude self
          if (firstSys) this.selectedMoveTargetId.set(firstSys.id);
      } else if (type === 'Feature') {
          // Default to current system for feature move context
          const currentSysId = this.dataService.selectedSystemId();
          if (currentSysId) this.targetSystemIdForFeature.set(currentSysId);
      }
  }

  executeMove() {
      const type = this.moveTargetType();
      const itemId = this.movingItemId();
      const targetId = this.selectedMoveTargetId();

      if (!itemId || !targetId) return;

      if (type === 'System') {
          // Demote System -> Subsystem
          if (confirm(`Convert System "${this.movingItemName()}" into a Subsystem of the selected target? This will restructure its contents.`)) {
              this.dataService.demoteSystem(itemId, targetId);
          }
      } else if (type === 'Subsystem') {
          // Move Subsystem -> New System
          this.dataService.moveSubsystem(itemId, targetId);
      } else if (type === 'Feature') {
          // Move Feature -> New Subsystem
          const sysId = this.targetSystemIdForFeature(); // System of the target subsystem
          if (sysId) {
             this.dataService.moveFeature(itemId, sysId, targetId);
          }
      }

      this.showMoveModal.set(false);
  }

  // Helper for Feature move modal: Filter subsystems based on selected System
  availableSubsystemsForFeature = computed(() => {
      if (this.moveTargetType() !== 'Feature') return [];
      const sysId = this.targetSystemIdForFeature();
      if (!sysId) return [];
      const sys = this.dataService.sortedSystems().find(s => s.id === sysId);
      // subsystems are pre-sorted in sortedSystems computed property
      return sys ? sys.subsystems : [];
  });

  // Helper for System/Subsystem move: List of Systems
  availableSystems = computed(() => {
      const type = this.moveTargetType();
      const movingId = this.movingItemId();
      const sorted = this.dataService.sortedSystems();
      // Exclude self if moving a system
      if (type === 'System') {
          return sorted.filter(s => s.id !== movingId);
      }
      return sorted;
  });
}

import { Component, inject, computed, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, AI_PLATFORMS, FolderCategory } from '../models/data.models';
import { FormsModule } from '@angular/forms';
import { BoardViewComponent } from './board-view.component';
import { TableViewComponent } from './table-view.component';
import { WorkSessionViewComponent } from './work-session-view.component';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule, BoardViewComponent, TableViewComponent, WorkSessionViewComponent],
  templateUrl: './kanban-board.component.html'
})
export class KanbanBoardComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  searchTerm = signal('');
  showModal = signal(false);
  showAiModal = signal(false);
  showApiKeyModal = signal(false);
  showExportModal = signal(false); // New modal for export
  isGenerating = signal(false);

  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');
  includeInProgress = signal(false);
  pendingExportReqIds = signal<string[]>([]); // Store IDs to update status later

  // Platform Data (Sorted)
  platforms = Object.keys(AI_PLATFORMS).sort((a, b) => a.localeCompare(b));
  availableModels = computed(() => {
    const models = AI_PLATFORMS[this.exportPlatform()] || [];
    return [...models].sort((a, b) => a.localeCompare(b));
  });

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // System Folders State (Sorted)
  readonly folderCategories: FolderCategory[] = ['Library', 'Service', 'UI'];
  newFolderName = signal('');
  newFolderCategory = signal<FolderCategory>('Library');
  newFolderNote = signal('');

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
  );

  selectedSubsystem = computed(() => {
    const sys = this.selectedSystem();
    return sys?.subsystems.find(s => s.id === this.dataService.selectedSubsystemId());
  });

  selectedFeature = computed(() => {
    const sub = this.selectedSubsystem();
    return sub?.features.find(f => f.id === this.dataService.selectedFeatureId());
  });

  // Current Documentation based on selection level
  currentReadme = computed(() => {
    if (this.selectedFeature()) return this.selectedFeature()!.readme || '';
    if (this.selectedSubsystem()) return this.selectedSubsystem()!.readme || '';
    if (this.selectedSystem()) return this.selectedSystem()!.readme || '';
    return '';
  });

  // Check if AI is available
  aiEnabled = computed(() => this.aiService.isConfigured());

  // Effect to update editor when selection changes
  constructor() {
    effect(() => {
        this.editableReadme.set(this.currentReadme());
    });

    // Set default model when platform changes
    effect(() => {
        const models = this.availableModels();
        if (models && models.length > 0) {
            this.exportModel.set(models[0]);
        }
    });
  }

  saveReadme() {
    const content = this.editableReadme();
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (feat && sub && sys) {
        this.dataService.updateFeatureReadme(sys.id, sub.id, feat.id, content);
    } else if (sub && sys) {
        this.dataService.updateSubsystemReadme(sys.id, sub.id, content);
    } else if (sys) {
        this.dataService.updateSystemReadme(sys.id, content);
    }
  }

  // --- Folder Logic ---
  addFolder() {
    const sys = this.selectedSystem();
    if (sys && this.newFolderName().trim()) {
        this.dataService.addSystemFolder(sys.id, {
            name: this.newFolderName(),
            category: this.newFolderCategory(),
            note: this.newFolderNote()
        });
        this.newFolderName.set('');
        this.newFolderNote.set('');
        this.newFolderCategory.set('Library');
    }
  }

  deleteFolder(folderId: string) {
     const sys = this.selectedSystem();
     if (sys) {
         if (confirm('Delete this folder?')) {
            this.dataService.deleteSystemFolder(sys.id, folderId);
         }
     }
  }

  getCategoryClass(category: FolderCategory) {
      switch(category) {
          case 'UI': return 'bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300';
          case 'Service': return 'bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300';
          case 'Library': return 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300';
          default: return 'bg-gray-100 text-gray-800';
      }
  }

  triggerImport(mode: 'append' | 'replace', input: HTMLInputElement) {
    this.importMode = mode;
    input.value = ''; // Reset to allow re-selecting same file
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input.files?.length) return;

    const file = input.files[0];
    const reader = new FileReader();

    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (this.importMode === 'replace') {
             if (!this.editableReadme() || confirm('This will replace the current documentation. Continue?')) {
                 this.editableReadme.set(text);
             }
        } else {
             const current = this.editableReadme();
             this.editableReadme.set(current ? current + '\n\n' + text : text);
        }
    };
    reader.readAsText(file);
  }

  filteredRequirements = computed(() => {
    let reqs = this.dataService.requirements();
    const fId = this.dataService.selectedFeatureId();
    const sId = this.dataService.selectedSubsystemId();
    const sysId = this.dataService.selectedSystemId();

    // Context Filtering
    if (fId) reqs = reqs.filter(r => r.featureId === fId);
    else if (sId) reqs = reqs.filter(r => r.subsystemId === sId);
    else if (sysId) reqs = reqs.filter(r => r.systemId === sysId);

    // Search Filtering
    const term = this.searchTerm().toLowerCase();
    if (term) {
        reqs = reqs.filter(r => 
            r.title.toLowerCase().includes(term) || 
            r.description.toLowerCase().includes(term)
        );
    }

    return reqs;
  });

  canAddRequirement = computed(() => !!this.selectedFeature());

  openAddModal() {
    this.editingReqId.set(null);
    this.newReqTitle = '';
    this.newReqDesc = '';
    this.newReqPriority = 'Medium';
    this.showModal.set(true);
  }

  openEditModal(req: Requirement) {
    this.editingReqId.set(req.id);
    this.newReqTitle = req.title;
    this.newReqDesc = req.description;
    this.newReqPriority = req.priority;
    this.showModal.set(true);
  }

  openAiModal() {
    if (!this.aiEnabled()) {
        this.apiKeyInput = '';
        this.showApiKeyModal.set(true);
        return;
    }
    this.userStoryPrompt = '';
    this.showAiModal.set(true);
  }

  configureApiKey() {
    if (this.apiKeyInput.trim()) {
        const success = this.aiService.configure(this.apiKeyInput.trim());
        if (success) {
            this.showApiKeyModal.set(false);
            // Do not automatically open the AI generation modal
        } else {
            alert('Failed to configure AI service.');
        }
    }
  }

  async generateAiRequirements() {
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (!feat || !sub || !sys || !this.userStoryPrompt.trim()) return;

    this.isGenerating.set(true);
    const context = `System: ${sys.name}, Subsystem: ${sub.name}, Feature: ${feat.name}`;

    let docStack = '';
    if (sys.readme) docStack += `[SYSTEM DOCS]:\n${sys.readme}\n\n`;
    if (sub.readme) docStack += `[SUBSYSTEM DOCS]:\n${sub.readme}\n\n`;
    if (feat.readme) docStack += `[FEATURE DOCS]:\n${feat.readme}\n\n`;

    try {
      const generated = await this.aiService.generateRequirements(context, docStack, this.userStoryPrompt);

      generated.forEach(req => {
        this.dataService.addRequirement({
          title: req.title,
          description: req.description,
          priority: req.priority,
          status: 'Backlog',
          systemId: sys.id,
          subsystemId: sub.id,
          featureId: feat.id
        });
      });

      this.showAiModal.set(false);
    } finally {
      this.isGenerating.set(false);
    }
  }

  saveManual() {
    // Edit mode
    const editId = this.editingReqId();
    if (editId) {
        this.dataService.updateRequirement(editId, {
            title: this.newReqTitle,
            description: this.newReqDesc,
            priority: this.newReqPriority
        });
        this.showModal.set(false);
        return;
    }

    // Create mode
    const feat = this.selectedFeature();
    if (!feat) return;

    this.dataService.addRequirement({
      title: this.newReqTitle,
      description: this.newReqDesc,
      priority: this.newReqPriority,
      status: 'Backlog',
      systemId: this.dataService.selectedSystemId()!,
      subsystemId: this.dataService.selectedSubsystemId()!,
      featureId: feat.id
    });
    this.showModal.set(false);
  }

  // --- Export Logic ---

  toggleExportFilter() {
     this.includeInProgress.update(v => !v);
     // Re-generate context with new filter
     this.generateExportContext(this.includeInProgress());
  }

  copyPrompt(req?: Requirement) {
      if (req) {
          // Single Requirement Export
          this.generateExportContext(false, req);
          this.showExportModal.set(true);
      } else {
          // Scope Export (Default: ToDo only)
          this.includeInProgress.set(false);
          this.generateExportContext(false);
          this.showExportModal.set(true);
      }
  }

  generateExportContext(includeInProgress: boolean, singleReq?: Requirement) {
    const sys = this.selectedSystem();
    const sub = this.selectedSubsystem();
    const feat = this.selectedFeature();

    let content = 'PROJECT CONTEXT\n===============\n';
    if (sys) content += `System: ${sys.name}\nDescription: ${sys.description}\n\n`;
    if (sub) content += `Subsystem: ${sub.name}\nDescription: ${sub.description}\n\n`;
    if (feat) content += `Feature: ${feat.name}\nDescription: ${feat.description}\n\n`;

    content += 'DOCUMENTATION\n=============\n';
    if (sys?.readme) content += `[SYSTEM: ${sys.name}]\n${sys.readme}\n\n`;
    if (sub?.readme) content += `[SUBSYSTEM: ${sub.name}]\n${sub.readme}\n\n`;
    if (feat?.readme) content += `[FEATURE: ${feat.name}]\n${feat.readme}\n\n`;

    // Add Folders to Context if System
    if (sys?.folders && sys.folders.length > 0) {
        content += `\n[SYSTEM STRUCTURE]\n`;
        sys.folders.forEach(f => {
            content += `- ${f.name} [${f.category}]: ${f.note}\n`;
        });
        content += `\n`;
    }

    if (singleReq) {
      content += 'SELECTED REQUIREMENT\n====================\n';
      content += `Title: ${singleReq.title}\n`;
      content += `Status: ${singleReq.status}\n`;
      content += `Priority: ${singleReq.priority}\n`;
      content += `Description:\n${singleReq.description}\n`;

      content += '\nTASK\n====\n';
      content += `[Generate implementation steps, test cases, or code for: "${singleReq.title}"]\n`;

      this.exportParentId.set(singleReq.id);
      this.exportParentType.set('Requirement');
      this.exportParentName.set(singleReq.title);
      this.pendingExportReqIds.set([]); // No status update for single export? Or should we? Assuming no for now based on req.
    } else {
        // ROLL-UP REQUIREMENTS LOGIC
        const allReqs = this.dataService.requirements();
        let scopeReqs: Requirement[] = [];

        if (feat) {
            scopeReqs = allReqs.filter(r => r.featureId === feat.id);
        } else if (sub) {
            scopeReqs = allReqs.filter(r => r.subsystemId === sub.id);
        } else if (sys) {
            scopeReqs = allReqs.filter(r => r.systemId === sys.id);
        } else {
             scopeReqs = allReqs; 
        }

        // Apply Status Filter
        // Default: ToDo. With Toggle: ToDo + InProgress
        const allowedStatuses: Status[] = includeInProgress ? ['ToDo', 'InProgress'] : ['ToDo'];

        const filteredReqs = scopeReqs.filter(r => allowedStatuses.includes(r.status));
        this.pendingExportReqIds.set(filteredReqs.map(r => r.id));

        if (filteredReqs.length > 0) {
            content += 'SCOPE REQUIREMENTS\n==================\n';
            filteredReqs.forEach((r, index) => {
                content += `${index + 1}. [${r.status}] ${r.title} (Priority: ${r.priority})\n`;
                if (r.description) {
                    content += `   Details: ${r.description.replace(/\n/g, '\n   ')}\n`;
                }
                content += '\n';
            });
        }

        content += 'TASK\n====\n';
        content += '[Enter instruction here, e.g., Implement the requirements listed above, Generate test plan, etc.]\n';

        // Determine parent scope IDs for the session record
        if (feat) {
            this.exportParentId.set(feat.id);
            this.exportParentType.set('Feature');
            this.exportParentName.set(feat.name);
        } else if (sub) {
            this.exportParentId.set(sub.id);
            this.exportParentType.set('Subsystem');
            this.exportParentName.set(sub.name);
        } else if (sys) {
            this.exportParentId.set(sys.id);
            this.exportParentType.set('System');
            this.exportParentName.set(sys.name);
        }
    }

    this.exportContextText.set(content);
  }

  saveExportSession() {
      // 1. Save to DB
      this.dataService.addWorkSession({
          parentId: this.exportParentId(),
          parentType: this.exportParentType(),
          parentName: this.exportParentName(),
          context: this.exportContextText(),
          platform: this.exportPlatform(),
          model: this.exportModel(),
          status: 'Pending'
      });

      // 2. Copy to Clipboard
      navigator.clipboard.writeText(this.exportContextText()).then(() => {
          alert('Session Created! Context copied to clipboard.');
      }).catch(err => {
          console.error('Copy failed', err);
          alert('Session Created, but failed to copy text automatically.');
      });

      // 3. Update Requirements Status
      // "exporting context should move all associated requirements the In Progress status."
      if (this.pendingExportReqIds().length > 0) {
          this.dataService.batchUpdateRequirementStatus(this.pendingExportReqIds(), 'InProgress');
      }

      // 4. Close & Reset
      this.showExportModal.set(false);
  }
}

import { Component, inject } from '@angular/core';
import { HierarchyNavComponent } from './components/hierarchy-nav.component';
import { KanbanBoardComponent } from './components/kanban-board.component';
import { DataService } from './services/data.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [HierarchyNavComponent, KanbanBoardComponent],
  templateUrl: './app.component.html'
})
export class AppComponent {
  dataService = inject(DataService);
}

import { Injectable, signal, computed, effect } from '@angular/core';
import { System, Subsystem, Feature, Requirement, Status, WorkSession, FolderCategory } from '../models/data.models';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  // --- State Signals ---
  readonly systems = signal<System[]>([]);
  readonly requirements = signal<Requirement[]>([]);
  readonly workSessions = signal<WorkSession[]>([]);

  // --- Computed State for UI ---
  readonly sortedSystems = computed(() => {
    const sortByName = (a: { name: string }, b: { name: string }) => a.name.localeCompare(b.name);

    return this.systems().map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => ({
        ...sub,
        features: [...sub.features].sort(sortByName)
      })).sort(sortByName)
    })).sort(sortByName);
  });

  // Global map of subsystem IDs to colors for easy lookup in views
  readonly subsystemColorMap = computed(() => {
    const map = new Map<string, string>();
    this.systems().forEach(sys => {
      sys.subsystems.forEach(sub => {
        if (sub.color) map.set(sub.id, sub.color);
      });
    });
    return map;
  });

  // --- UI State ---
  readonly darkMode = signal<boolean>(false);
  readonly viewMode = signal<'board' | 'table' | 'docs' | 'sessions'>('board');

  // --- Selection State ---
  readonly selectedSystemId = signal<string | null>(null);
  readonly selectedSubsystemId = signal<string | null>(null);
  readonly selectedFeatureId = signal<string | null>(null);

  // Palette for subsystems
  private readonly colorPalette = [
    '#EF4444', // Red
    '#F97316', // Orange
    '#F59E0B', // Amber
    '#10B981', // Emerald
    '#06B6D4', // Cyan
    '#3B82F6', // Blue
    '#6366F1', // Indigo
    '#8B5CF6', // Violet
    '#EC4899', // Pink
    '#F43F5E', // Rose
    '#84CC16', // Lime
    '#14B8A6', // Teal
  ];

  constructor() {
    this.loadFromStorage();
    this.initTheme();

    // Auto-save data
    effect(() => {
      localStorage.setItem('nebula_systems', JSON.stringify(this.systems()));
      localStorage.setItem('nebula_requirements', JSON.stringify(this.requirements()));
      localStorage.setItem('nebula_sessions', JSON.stringify(this.workSessions()));
    });

    // Auto-save theme & Apply to DOM
    effect(() => {
      const isDark = this.darkMode();
      localStorage.setItem('nebula_dark_mode', String(isDark));
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    });
  }

  private loadFromStorage() {
    const savedSystems = localStorage.getItem('nebula_systems');
    const savedReqs = localStorage.getItem('nebula_requirements');
    const savedSessions = localStorage.getItem('nebula_sessions');

    if (savedSystems) {
      this.systems.set(JSON.parse(savedSystems));
    } else {
      // Seed data if empty
      this.seedData();
    }

    if (savedReqs) {
      this.requirements.set(JSON.parse(savedReqs));
    }

    if (savedSessions) {
      this.workSessions.set(JSON.parse(savedSessions));
    }
  }

  private initTheme() {
    const saved = localStorage.getItem('nebula_dark_mode');
    if (saved !== null) {
        this.darkMode.set(saved === 'true');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        this.darkMode.set(true);
    }
  }

  toggleTheme() {
    this.darkMode.update(d => !d);
  }

  private getUniqueColor(systemId: string): string {
    const system = this.systems().find(s => s.id === systemId);
    if (!system) return this.colorPalette[0];

    const usedColors = new Set(system.subsystems.map(s => s.color));

    // Find first unused color
    const available = this.colorPalette.find(c => !usedColors.has(c));

    // Return available or random if all used
    return available || this.colorPalette[Math.floor(Math.random() * this.colorPalette.length)];
  }

  private seedData() {
    const sysId = crypto.randomUUID();
    const subId = crypto.randomUUID();
    const featId = crypto.randomUUID();

    const initialSystem: System = {
      id: sysId,
      name: 'E-Commerce Platform',
      description: 'Main customer facing retail platform',
      readme: '# E-Commerce Platform Architecture\nThis system handles all customer-facing interactions.\n\n## Tech Stack\n- Angular 18\n- Node.js API\n- PostgreSQL',
      folders: [
        { id: crypto.randomUUID(), name: 'webapp', category: 'UI', note: 'Main storefront angular app' },
        { id: crypto.randomUUID(), name: 'api-gateway', category: 'Service', note: 'BFF for mobile and web' }
      ],
      subsystems: [{
        id: subId,
        name: 'Checkout',
        description: 'Payment and Order processing',
        readme: '## Checkout Flow\n1. Cart validation\n2. User auth check\n3. Shipping address\n4. Payment processing',
        color: '#10B981',
        systemId: sysId,
        features: [{
          id: featId,
          name: 'Payment Gateway',
          description: 'Stripe and PayPal integration',
          readme: 'Integration requirements for Stripe v3 API.',
          subsystemId: subId
        }]
      }]
    };
    this.systems.set([initialSystem]);

    // Select the first item by default for better UX
    this.selectedSystemId.set(sysId);
  }

  // --- Import / Export ---
  exportDatabase() {
    const data = {
      systems: this.systems(),
      requirements: this.requirements(),
      workSessions: this.workSessions(),
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      }
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nebula-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    window.URL.revokeObjectURL(url);
  }

  importDatabase(file: File) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (json.systems && Array.isArray(json.systems)) {
          this.systems.set(json.systems);
        }
        if (json.requirements && Array.isArray(json.requirements)) {
          this.requirements.set(json.requirements);
        }
        if (json.workSessions && Array.isArray(json.workSessions)) {
          this.workSessions.set(json.workSessions);
        }
        alert('Database restored successfully!');
      } catch (err) {
        console.error(err);
        alert('Failed to parse backup file.');
      }
    };
    reader.readAsText(file);
  }

  // --- Actions ---

  addSystem(name: string, description: string) {
    const newSystem: System = {
      id: crypto.randomUUID(),
      name,
      description,
      folders: [],
      subsystems: []
    };
    this.systems.update(s => [...s, newSystem]);
  }

  addSubsystem(systemId: string, name: string, description: string) {
    const color = this.getUniqueColor(systemId);

    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: [...sys.subsystems, {
            id: crypto.randomUUID(),
            name,
            description,
            color,
            features: [],
            systemId
          }]
        };
      }
      return sys;
    }));
  }

  updateSubsystemColor(systemId: string, subsystemId: string, color: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => 
             sub.id === subsystemId ? { ...sub, color } : sub
          )
        };
      }
      return sys;
    }));
  }

  addFeature(systemId: string, subsystemId: string, name: string, description: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subsystemId) {
            return {
              ...sub,
              features: [...sub.features, {
                id: crypto.randomUUID(),
                name,
                description,
                subsystemId
              }]
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
  }

  // --- Rename Methods ---
  updateSystemName(id: string, name: string) {
    this.systems.update(systems => 
        systems.map(sys => 
            sys.id === id ? { ...sys, name } : sys
        )
    );
  }

  updateSubsystemName(systemId: string, subsystemId: string, name: string) {
      this.systems.update(systems => 
          systems.map(sys => {
              if (sys.id === systemId) {
                  return {
                      ...sys,
                      subsystems: sys.subsystems.map(sub => 
                          sub.id === subsystemId ? { ...sub, name } : sub
                      )
                  };
              }
              return sys;
          })
      );
  }

  updateFeatureName(systemId: string, subsystemId: string, featureId: string, name: string) {
      this.systems.update(systems => 
          systems.map(sys => {
              if (sys.id === systemId) {
                  return {
                      ...sys,
                      subsystems: sys.subsystems.map(sub => {
                          if (sub.id === subsystemId) {
                              return {
                                  ...sub,
                                  features: sub.features.map(feat => 
                                      feat.id === featureId ? { ...feat, name } : feat
                                  )
                              };
                          }
                          return sub;
                      })
                  };
              }
              return sys;
          })
      );
  }

  // --- Folder Management ---

  addSystemFolder(systemId: string, folder: { name: string, category: FolderCategory, note: string }) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: [...(sys.folders || []), {
            id: crypto.randomUUID(),
            ...folder
          }]
        };
      }
      return sys;
    }));
  }

  deleteSystemFolder(systemId: string, folderId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          folders: (sys.folders || []).filter(f => f.id !== folderId)
        };
      }
      return sys;
    }));
  }

  // --- Documentation Updates ---

  updateSystemReadme(id: string, readme: string) {
    this.systems.update(s => s.map(sys => sys.id === id ? { ...sys, readme } : sys));
  }

  updateSubsystemReadme(sysId: string, subId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        return {
          ...sys,
          subsystems: sys.subsystems.map(sub => sub.id === subId ? { ...sub, readme } : sub)
        };
      }
      return sys;
    }));
  }

  updateFeatureReadme(sysId: string, subId: string, featId: string, readme: string) {
    this.systems.update(s => s.map(sys => {
      if (sys.id === sysId) {
        const subs = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.map(f => f.id === featId ? { ...f, readme } : f)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: subs };
      }
      return sys;
    }));
  }

  addRequirement(req: Omit<Requirement, 'id' | 'createdAt'>) {
    const newReq: Requirement = {
      ...req,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    this.requirements.update(r => [...r, newReq]);
  }

  updateRequirementStatus(id: string, newStatus: Status) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, status: newStatus } : r
    ));
  }

  // Batch update for Export Rollup
  batchUpdateRequirementStatus(ids: string[], newStatus: Status) {
      if (!ids.length) return;
      this.requirements.update(reqs => reqs.map(r => 
        ids.includes(r.id) ? { ...r, status: newStatus } : r
      ));
  }

  updateRequirement(id: string, updates: Partial<Requirement>) {
    this.requirements.update(reqs => reqs.map(r => 
      r.id === id ? { ...r, ...updates } : r
    ));
  }

  deleteRequirement(id: string) {
    this.requirements.update(reqs => reqs.filter(r => r.id !== id));
  }

  deleteSystem(id: string) {
    this.systems.update(s => s.filter(sys => sys.id !== id));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.systemId !== id));
    // Cascade delete sessions
    this.workSessions.update(ws => ws.filter(s => s.parentId !== id)); 

    if (this.selectedSystemId() === id) {
      this.selectedSystemId.set(null);
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteSubsystem(systemId: string, subId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        return {
          ...sys,
          subsystems: sys.subsystems.filter(sub => sub.id !== subId)
        };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.subsystemId !== subId));

    if (this.selectedSubsystemId() === subId) {
      this.selectedSubsystemId.set(null);
      this.selectedFeatureId.set(null);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string) {
    this.systems.update(systems => systems.map(sys => {
      if (sys.id === systemId) {
        const updatedSubsystems = sys.subsystems.map(sub => {
          if (sub.id === subId) {
            return {
              ...sub,
              features: sub.features.filter(f => f.id !== featId)
            };
          }
          return sub;
        });
        return { ...sys, subsystems: updatedSubsystems };
      }
      return sys;
    }));
    // Cascade delete requirements
    this.requirements.update(reqs => reqs.filter(r => r.featureId !== featId));

    if (this.selectedFeatureId() === featId) {
      this.selectedFeatureId.set(null);
    }
  }

  // --- Rearrange / Move Logic ---

  moveFeature(featureId: string, targetSystemId: string, targetSubsystemId: string) {
    // 1. Find the feature and remove from old location
    let feature: Feature | undefined;
    this.systems.update(systems => systems.map(sys => ({
      ...sys,
      subsystems: sys.subsystems.map(sub => {
        const found = sub.features.find(f => f.id === featureId);
        if (found) {
            feature = found;
            return { ...sub, features: sub.features.filter(f => f.id !== featureId) };
        }
        return sub;
      })
    })));

    if (!feature) return;

    // 2. Add to new location
    feature.subsystemId = targetSubsystemId;
    this.systems.update(systems => systems.map(sys => {
        if (sys.id === targetSystemId) {
            return {
                ...sys,
                subsystems: sys.subsystems.map(sub => {
                    if (sub.id === targetSubsystemId) {
                        return { ...sub, features: [...sub.features, feature!] };
                    }
                    return sub;
                })
            }
        }
        return sys;
    }));

    // 3. Update Requirements
    this.requirements.update(reqs => reqs.map(r => {
        if (r.featureId === featureId) {
            return { ...r, systemId: targetSystemId, subsystemId: targetSubsystemId };
        }
        return r;
    }));
  }

  moveSubsystem(subsystemId: string, targetSystemId: string) {
     let subsystem: Subsystem | undefined;

     // 1. Find and remove from old system
     this.systems.update(systems => systems.map(sys => {
         const found = sys.subsystems.find(s => s.id === subsystemId);
         if (found) {
             subsystem = found;
             return { ...sys, subsystems: sys.subsystems.filter(s => s.id !== subsystemId) };
         }
         return sys;
     }));

     if (!subsystem) return;

     // 2. Add to new system
     subsystem.systemId = targetSystemId;
     this.systems.update(systems => systems.map(sys => {
         if (sys.id === targetSystemId) {
             return { ...sys, subsystems: [...sys.subsystems, subsystem!] };
         }
         return sys;
     }));

     // 3. Update Requirements
     this.requirements.update(reqs => reqs.map(r => {
         if (r.subsystemId === subsystemId) {
             return { ...r, systemId: targetSystemId };
         }
         return r;
     }));
  }

  // Demote a System to become a Subsystem of another System
  demoteSystem(sourceSystemId: string, targetSystemId: string) {
      const allSystems = this.systems();
      const sourceSystem = allSystems.find(s => s.id === sourceSystemId);
      const targetSystem = allSystems.find(s => s.id === targetSystemId);

      if (!sourceSystem || !targetSystem) return;

      // 1. Create a new Subsystem in Target based on Source System
      const newSubsystemId = crypto.randomUUID();
      const newSubsystem: Subsystem = {
          id: newSubsystemId,
          name: sourceSystem.name,
          description: sourceSystem.description,
          readme: sourceSystem.readme,
          color: this.getUniqueColor(targetSystemId),
          systemId: targetSystemId,
          features: []
      };

      // 2. Convert Source Subsystems into Features for the new Subsystem
      sourceSystem.subsystems.forEach(oldSub => {
          const newFeature: Feature = {
              id: crypto.randomUUID(), // New ID to be safe, or keep old? Keeping old might break references if types mix. Let's keep ID to save req references where possible, but Feature schema != Subsystem schema.
              // Actually, simpler to keep ID if we are careful, BUT 'Subsystem' has features, 'Feature' doesn't.
              // We must Flatten.
              name: oldSub.name,
              description: oldSub.description,
              readme: oldSub.readme,
              subsystemId: newSubsystemId
          };

          // Add this "Converted Feature" to the new Subsystem
          newSubsystem.features.push(newFeature);

          // Update Requirements linked to the OLD Subsystem to point to the NEW Feature
          // And also update their System ID.
          // OLD: systemId=source, subsystemId=oldSub.id, featureId=null
          // NEW: systemId=target, subsystemId=newSubsystemId, featureId=newFeature.id
          this.requirements.update(reqs => reqs.map(r => {
              if (r.subsystemId === oldSub.id) {
                  return { 
                      ...r, 
                      systemId: targetSystemId, 
                      subsystemId: newSubsystemId, 
                      featureId: newFeature.id // Link reqs that were at subsystem level to this new feature
                  };
              }
              return r;
          }));

          // What about reqs that were inside Features of the old Subsystem?
          // They need to be moved to the new Feature as well (Flattened) because Features can't have Features.
          // OLD: featureId IN oldSub.features
          const oldFeatureIds = oldSub.features.map(f => f.id);
          this.requirements.update(reqs => reqs.map(r => {
              if (oldFeatureIds.includes(r.featureId)) {
                   return {
                       ...r,
                       systemId: targetSystemId,
                       subsystemId: newSubsystemId,
                       featureId: newFeature.id // Flattened into the converted feature
                   };
              }
              return r;
          }));
      });

      // 3. Handle Direct Requirements of the Source System (no subsystem)
      // They move to the new Subsystem (no feature)
      this.requirements.update(reqs => reqs.map(r => {
          if (r.systemId === sourceSystemId && !r.subsystemId) {
              return {
                  ...r,
                  systemId: targetSystemId,
                  subsystemId: newSubsystemId
              };
          }
          return r;
      }));

      // 4. Add the new Subsystem to the Target System state
      this.systems.update(systems => systems.map(sys => {
          if (sys.id === targetSystemId) {
              return { ...sys, subsystems: [...sys.subsystems, newSubsystem] };
          }
          return sys;
      }));

      // 5. Delete the old Source System
      // (This automatically filters out the old system from the array)
      this.systems.update(sys => sys.filter(s => s.id !== sourceSystemId));

      // 6. Reset Selection
      this.selectedSystemId.set(targetSystemId);
      this.selectedSubsystemId.set(newSubsystemId);
      this.selectedFeatureId.set(null);
  }

  // --- Work Sessions ---
  addWorkSession(session: Omit<WorkSession, 'id' | 'createdAt' | 'updatedAt'>) {
    const newSession: WorkSession = {
        ...session,
        id: crypto.randomUUID(),
        createdAt: Date.now(),
        updatedAt: Date.now()
    };
    this.workSessions.update(s => [newSession, ...s]);
  }

  updateWorkSession(id: string, updates: Partial<WorkSession>) {
      this.workSessions.update(sessions => sessions.map(s => 
          s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
      ));
  }

  deleteWorkSession(id: string) {
      this.workSessions.update(s => s.filter(session => session.id !== id));
  }
}

import { Component, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';
import { System, Subsystem, Feature } from '../models/data.models';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  // --- Inline Editing State ---
  editingItem = signal<{ type: 'System' | 'Subsystem' | 'Feature', id: string, systemId?: string, subsystemId?: string } | null>(null);
  editingName = signal('');

  // --- Move/Reparent Modal State ---
  showMoveModal = signal(false);
  moveTargetType = signal<'System' | 'Subsystem' | 'Feature'>('System'); // What we are moving
  movingItemId = signal<string | null>(null);
  movingItemName = signal<string>('');

  // For Feature Move:
  targetSystemIdForFeature = signal<string>('');

  // Selection
  selectedMoveTargetId = signal<string>('');

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  // --- Import / Export ---
  triggerExport() {
    this.dataService.exportDatabase();
  }

  triggerImport(input: HTMLInputElement) {
    input.value = '';
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      this.dataService.importDatabase(input.files[0]);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }

  // --- Inline Editing Logic ---
  startEditing(
      type: 'System' | 'Subsystem' | 'Feature', 
      item: {id: string, name: string}, 
      event: Event, 
      systemId?: string, 
      subsystemId?: string
  ) {
      event.stopPropagation();
      this.editingItem.set({ type, id: item.id, systemId, subsystemId });
      this.editingName.set(item.name);
  }

  saveEdit() {
      const item = this.editingItem();
      const newName = this.editingName().trim();
      if (!item || !newName) {
          this.cancelEdit();
          return;
      }

      switch(item.type) {
          case 'System':
              this.dataService.updateSystemName(item.id, newName);
              break;
          case 'Subsystem':
              if (item.systemId) {
                  this.dataService.updateSubsystemName(item.systemId, item.id, newName);
              }
              break;
          case 'Feature':
              if (item.systemId && item.subsystemId) {
                  this.dataService.updateFeatureName(item.systemId, item.subsystemId, item.id, newName);
              }
              break;
      }

      this.cancelEdit();
  }

  cancelEdit() {
      this.editingItem.set(null);
      this.editingName.set('');
  }

  // --- Move Logic ---

  initiateMove(type: 'System' | 'Subsystem' | 'Feature', item: System | Subsystem | Feature, event: Event) {
      event.stopPropagation();
      this.moveTargetType.set(type);
      this.movingItemId.set(item.id);
      this.movingItemName.set(item.name);
      this.selectedMoveTargetId.set('');
      this.showMoveModal.set(true);

      // Pre-select first valid target if possible
      if (type === 'System' || type === 'Subsystem') {
          const firstSys = this.dataService.systems().find(s => s.id !== item.id); // Exclude self
          if (firstSys) this.selectedMoveTargetId.set(firstSys.id);
      } else if (type === 'Feature') {
          // Default to current system for feature move context
          const currentSysId = this.dataService.selectedSystemId();
          if (currentSysId) this.targetSystemIdForFeature.set(currentSysId);
      }
  }

  executeMove() {
      const type = this.moveTargetType();
      const itemId = this.movingItemId();
      const targetId = this.selectedMoveTargetId();

      if (!itemId || !targetId) return;

      if (type === 'System') {
          // Demote System -> Subsystem
          if (confirm(`Convert System "${this.movingItemName()}" into a Subsystem of the selected target? This will restructure its contents.`)) {
              this.dataService.demoteSystem(itemId, targetId);
          }
      } else if (type === 'Subsystem') {
          // Move Subsystem -> New System
          this.dataService.moveSubsystem(itemId, targetId);
      } else if (type === 'Feature') {
          // Move Feature -> New Subsystem
          const sysId = this.targetSystemIdForFeature(); // System of the target subsystem
          if (sysId) {
             this.dataService.moveFeature(itemId, sysId, targetId);
          }
      }

      this.showMoveModal.set(false);
  }

  // Helper for Feature move modal: Filter subsystems based on selected System
  availableSubsystemsForFeature = computed(() => {
      if (this.moveTargetType() !== 'Feature') return [];
      const sysId = this.targetSystemIdForFeature();
      if (!sysId) return [];
      const sys = this.dataService.sortedSystems().find(s => s.id === sysId);
      // subsystems are pre-sorted in sortedSystems computed property
      return sys ? sys.subsystems : [];
  });

  // Helper for System/Subsystem move: List of Systems
  availableSystems = computed(() => {
      const type = this.moveTargetType();
      const movingId = this.movingItemId();
      const sorted = this.dataService.sortedSystems();
      // Exclude self if moving a system
      if (type === 'System') {
          return sorted.filter(s => s.id !== movingId);
      }
      return sorted;
  });
}

import { Component, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { FormsModule } from '@angular/forms';
import { System, Subsystem, Feature } from '../models/data.models';

@Component({
  selector: 'app-hierarchy-nav',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './hierarchy-nav.component.html'
})
export class HierarchyNavComponent {
  dataService = inject(DataService);

  isAddingSystem = signal(false);
  addingSubsystemTo = signal<string | null>(null);
  addingFeatureTo = signal<string | null>(null);

  newSystemName = '';
  newSubsystemName = '';
  newFeatureName = '';

  // --- Collapsible State ---
  collapsedSystems = signal(new Set<string>());
  collapsedSubsystems = signal(new Set<string>());

  // --- Inline Editing State ---
  editingItem = signal<{ type: 'System' | 'Subsystem' | 'Feature', id: string, systemId?: string, subsystemId?: string } | null>(null);
  editingName = signal('');

  // --- Move/Reparent Modal State ---
  showMoveModal = signal(false);
  moveTargetType = signal<'System' | 'Subsystem' | 'Feature'>('System'); // What we are moving
  movingItemId = signal<string | null>(null);
  movingItemName = signal<string>('');

  // For Feature Move:
  targetSystemIdForFeature = signal<string>('');

  // Selection
  selectedMoveTargetId = signal<string>('');

  selectSystem(id: string) {
    this.dataService.selectedSystemId.set(id);
    this.dataService.selectedSubsystemId.set(null);
    this.dataService.selectedFeatureId.set(null);
    // Expand when selected
    this.collapsedSystems.update(set => {
      const newSet = new Set(set);
      newSet.delete(id);
      return newSet;
    });
  }

  selectSubsystem(systemId: string, subId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(null);
    // Expand subsystem and its parent system
    this.collapsedSystems.update(set => {
      const newSet = new Set(set);
      newSet.delete(systemId);
      return newSet;
    });
    this.collapsedSubsystems.update(set => {
      const newSet = new Set(set);
      newSet.delete(subId);
      return newSet;
    });
  }

  selectFeature(systemId: string, subId: string, featureId: string) {
    this.dataService.selectedSystemId.set(systemId);
    this.dataService.selectedSubsystemId.set(subId);
    this.dataService.selectedFeatureId.set(featureId);
     // Expand parents
     this.collapsedSystems.update(set => {
      const newSet = new Set(set);
      newSet.delete(systemId);
      return newSet;
    });
    this.collapsedSubsystems.update(set => {
      const newSet = new Set(set);
      newSet.delete(subId);
      return newSet;
    });
  }

  createSystem() {
    if (this.newSystemName.trim()) {
      this.dataService.addSystem(this.newSystemName, '');
      this.newSystemName = '';
      this.isAddingSystem.set(false);
    }
  }

  createSubsystem(systemId: string) {
    if (this.newSubsystemName.trim()) {
      this.dataService.addSubsystem(systemId, this.newSubsystemName, '');
      this.newSubsystemName = '';
      this.addingSubsystemTo.set(null);
    }
  }

  createFeature(systemId: string, subsystemId: string) {
     if (this.newFeatureName.trim()) {
      this.dataService.addFeature(systemId, subsystemId, this.newFeatureName, '');
      this.newFeatureName = '';
      this.addingFeatureTo.set(null);
    }
  }

  updateSubsystemColor(systemId: string, subId: string, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input && input.value) {
        this.dataService.updateSubsystemColor(systemId, subId, input.value);
    }
  }

  // --- Import / Export ---
  triggerExport() {
    this.dataService.exportDatabase();
  }

  triggerImport(input: HTMLInputElement) {
    input.value = '';
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      this.dataService.importDatabase(input.files[0]);
    }
  }

  deleteSystem(id: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this system? All subsystems and requirements inside it will be lost.')) {
      this.dataService.deleteSystem(id);
    }
  }

  deleteSubsystem(systemId: string, subId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this subsystem? All features and requirements inside it will be lost.')) {
      this.dataService.deleteSubsystem(systemId, subId);
    }
  }

  deleteFeature(systemId: string, subId: string, featId: string, event: Event) {
    event.stopPropagation();
    if (confirm('Delete this feature? All requirements inside it will be lost.')) {
      this.dataService.deleteFeature(systemId, subId, featId);
    }
  }

  // --- Collapsible Logic ---
  toggleSystem(id: string, event: Event) {
    event.stopPropagation();
    this.collapsedSystems.update(set => {
      const newSet = new Set(set);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      return newSet;
    });
  }

  isSystemCollapsed(id: string): boolean {
    return this.collapsedSystems().has(id);
  }

  toggleSubsystem(id: string, event: Event) {
    event.stopPropagation();
    this.collapsedSubsystems.update(set => {
      const newSet = new Set(set);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      return newSet;
    });
  }

  isSubsystemCollapsed(id: string): boolean {
    return this.collapsedSubsystems().has(id);
  }


  // --- Inline Editing Logic ---
  startEditing(
      type: 'System' | 'Subsystem' | 'Feature', 
      item: {id: string, name: string}, 
      event: Event, 
      systemId?: string, 
      subsystemId?: string
  ) {
      event.stopPropagation();
      this.editingItem.set({ type, id: item.id, systemId, subsystemId });
      this.editingName.set(item.name);
  }

  saveEdit() {
      const item = this.editingItem();
      const newName = this.editingName().trim();
      if (!item || !newName) {
          this.cancelEdit();
          return;
      }

      switch(item.type) {
          case 'System':
              this.dataService.updateSystemName(item.id, newName);
              break;
          case 'Subsystem':
              if (item.systemId) {
                  this.dataService.updateSubsystemName(item.systemId, item.id, newName);
              }
              break;
          case 'Feature':
              if (item.systemId && item.subsystemId) {
                  this.dataService.updateFeatureName(item.systemId, item.subsystemId, item.id, newName);
              }
              break;
      }

      this.cancelEdit();
  }

  cancelEdit() {
      this.editingItem.set(null);
      this.editingName.set('');
  }

  // --- Move Logic ---

  initiateMove(type: 'System' | 'Subsystem' | 'Feature', item: System | Subsystem | Feature, event: Event) {
      event.stopPropagation();
      this.moveTargetType.set(type);
      this.movingItemId.set(item.id);
      this.movingItemName.set(item.name);
      this.selectedMoveTargetId.set('');
      this.showMoveModal.set(true);

      // Pre-select first valid target if possible
      if (type === 'System' || type === 'Subsystem') {
          const firstSys = this.dataService.systems().find(s => s.id !== item.id); // Exclude self
          if (firstSys) this.selectedMoveTargetId.set(firstSys.id);
      } else if (type === 'Feature') {
          // Default to current system for feature move context
          const currentSysId = this.dataService.selectedSystemId();
          if (currentSysId) this.targetSystemIdForFeature.set(currentSysId);
      }
  }

  executeMove() {
      const type = this.moveTargetType();
      const itemId = this.movingItemId();
      const targetId = this.selectedMoveTargetId();

      if (!itemId || !targetId) return;

      if (type === 'System') {
          // Demote System -> Subsystem
          if (confirm(`Convert System "${this.movingItemName()}" into a Subsystem of the selected target? This will restructure its contents.`)) {
              this.dataService.demoteSystem(itemId, targetId);
          }
      } else if (type === 'Subsystem') {
          // Move Subsystem -> New System
          this.dataService.moveSubsystem(itemId, targetId);
      } else if (type === 'Feature') {
          // Move Feature -> New Subsystem
          const sysId = this.targetSystemIdForFeature(); // System of the target subsystem
          if (sysId) {
             this.dataService.moveFeature(itemId, sysId, targetId);
          }
      }

      this.showMoveModal.set(false);
  }

  // Helper for Feature move modal: Filter subsystems based on selected System
  availableSubsystemsForFeature = computed(() => {
      if (this.moveTargetType() !== 'Feature') return [];
      const sysId = this.targetSystemIdForFeature();
      if (!sysId) return [];
      const sys = this.dataService.sortedSystems().find(s => s.id === sysId);
      // subsystems are pre-sorted in sortedSystems computed property
      return sys ? sys.subsystems : [];
  });

  // Helper for System/Subsystem move: List of Systems
  availableSystems = computed(() => {
      const type = this.moveTargetType();
      const movingId = this.movingItemId();
      const sorted = this.dataService.sortedSystems();
      // Exclude self if moving a system
      if (type === 'System') {
          return sorted.filter(s => s.id !== movingId);
      }
      return sorted;
  });
}

import { Component, inject, computed, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, AI_PLATFORMS, FolderCategory } from '../models/data.models';
import { FormsModule } from '@angular/forms';
import { BoardViewComponent } from './board-view.component';
import { TableViewComponent } from './table-view.component';
import { WorkSessionViewComponent } from './work-session-view.component';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule, BoardViewComponent, TableViewComponent, WorkSessionViewComponent],
  templateUrl: './kanban-board.component.html'
})
export class KanbanBoardComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  searchTerm = signal('');
  showModal = signal(false);
  showAiModal = signal(false);
  showApiKeyModal = signal(false);
  showExportModal = signal(false); // New modal for export
  isGenerating = signal(false);

  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');
  includeInProgress = signal(false);
  pendingExportReqIds = signal<string[]>([]); // Store IDs to update status later

  // Platform Data (Sorted)
  platforms = Object.keys(AI_PLATFORMS).sort((a, b) => a.localeCompare(b));
  availableModels = computed(() => {
    const models = AI_PLATFORMS[this.exportPlatform()] || [];
    return [...models].sort((a, b) => a.localeCompare(b));
  });

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // System Folders State (Sorted)
  readonly folderCategories: FolderCategory[] = ['Library', 'Service', 'UI'];
  newFolderName = signal('');
  newFolderCategory = signal<FolderCategory>('Library');
  newFolderNote = signal('');

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
  );

  selectedSubsystem = computed(() => {
    const sys = this.selectedSystem();
    return sys?.subsystems.find(s => s.id === this.dataService.selectedSubsystemId());
  });

  selectedFeature = computed(() => {
    const sub = this.selectedSubsystem();
    return sub?.features.find(f => f.id === this.dataService.selectedFeatureId());
  });

  // Current Documentation based on selection level
  currentReadme = computed(() => {
    if (this.selectedFeature()) return this.selectedFeature()!.readme || '';
    if (this.selectedSubsystem()) return this.selectedSubsystem()!.readme || '';
    if (this.selectedSystem()) return this.selectedSystem()!.readme || '';
    return '';
  });

  // Check if AI is available
  aiEnabled = computed(() => this.aiService.isConfigured());

  // Effect to update editor when selection changes
  constructor() {
    effect(() => {
        this.editableReadme.set(this.currentReadme());
    });

    // Set default model when platform changes
    effect(() => {
        const models = this.availableModels();
        if (models && models.length > 0) {
            this.exportModel.set(models[0]);
        }
    });
  }

  saveReadme() {
    const content = this.editableReadme();
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (feat && sub && sys) {
        this.dataService.updateFeatureReadme(sys.id, sub.id, feat.id, content);
    } else if (sub && sys) {
        this.dataService.updateSubsystemReadme(sys.id, sub.id, content);
    } else if (sys) {
        this.dataService.updateSystemReadme(sys.id, content);
    }
  }

  // --- Folder Logic ---
  addFolder() {
    const sys = this.selectedSystem();
    if (sys && this.newFolderName().trim()) {
        this.dataService.addSystemFolder(sys.id, {
            name: this.newFolderName(),
            category: this.newFolderCategory(),
            note: this.newFolderNote()
        });
        this.newFolderName.set('');
        this.newFolderNote.set('');
        this.newFolderCategory.set('Library');
    }
  }

  deleteFolder(folderId: string) {
     const sys = this.selectedSystem();
     if (sys) {
         if (confirm('Delete this folder?')) {
            this.dataService.deleteSystemFolder(sys.id, folderId);
         }
     }
  }

  getCategoryClass(category: FolderCategory) {
      switch(category) {
          case 'UI': return 'bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300';
          case 'Service': return 'bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300';
          case 'Library': return 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300';
          default: return 'bg-gray-100 text-gray-800';
      }
  }

  triggerImport(mode: 'append' | 'replace', input: HTMLInputElement) {
    this.importMode = mode;
    input.value = ''; // Reset to allow re-selecting same file
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input.files?.length) return;

    const file = input.files[0];
    const reader = new FileReader();

    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (this.importMode === 'replace') {
             if (!this.editableReadme() || confirm('This will replace the current documentation. Continue?')) {
                 this.editableReadme.set(text);
             }
        } else {
             const current = this.editableReadme();
             this.editableReadme.set(current ? current + '\n\n' + text : text);
        }
    };
    reader.readAsText(file);
  }

  filteredRequirements = computed(() => {
    let reqs = this.dataService.requirements();
    const fId = this.dataService.selectedFeatureId();
    const sId = this.dataService.selectedSubsystemId();
    const sysId = this.dataService.selectedSystemId();

    // Context Filtering
    if (fId) reqs = reqs.filter(r => r.featureId === fId);
    else if (sId) reqs = reqs.filter(r => r.subsystemId === sId);
    else if (sysId) reqs = reqs.filter(r => r.systemId === sysId);

    // Search Filtering
    const term = this.searchTerm().toLowerCase();
    if (term) {
        reqs = reqs.filter(r => 
            r.title.toLowerCase().includes(term) || 
            r.description.toLowerCase().includes(term)
        );
    }

    return reqs;
  });

  canAddRequirement = computed(() => !!this.selectedFeature());

  openAddModal() {
    this.editingReqId.set(null);
    this.newReqTitle = '';
    this.newReqDesc = '';
    this.newReqPriority = 'Medium';
    this.showModal.set(true);
  }

  openEditModal(req: Requirement) {
    this.editingReqId.set(req.id);
    this.newReqTitle = req.title;
    this.newReqDesc = req.description;
    this.newReqPriority = req.priority;
    this.showModal.set(true);
  }

  openAiModal() {
    if (!this.aiEnabled()) {
        this.apiKeyInput = '';
        this.showApiKeyModal.set(true);
        return;
    }
    this.userStoryPrompt = '';
    this.showAiModal.set(true);
  }

  configureApiKey() {
    if (this.apiKeyInput.trim()) {
        const success = this.aiService.configure(this.apiKeyInput.trim());
        if (success) {
            this.showApiKeyModal.set(false);
            // Do not automatically open the AI generation modal
        } else {
            alert('Failed to configure AI service.');
        }
    }
  }

  async generateAiRequirements() {
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (!feat || !sub || !sys || !this.userStoryPrompt.trim()) return;

    this.isGenerating.set(true);
    const context = `System: ${sys.name}, Subsystem: ${sub.name}, Feature: ${feat.name}`;

    let docStack = '';
    if (sys.readme) docStack += `[SYSTEM DOCS]:\n${sys.readme}\n\n`;
    if (sub.readme) docStack += `[SUBSYSTEM DOCS]:\n${sub.readme}\n\n`;
    if (feat.readme) docStack += `[FEATURE DOCS]:\n${feat.readme}\n\n`;

    try {
      const generated = await this.aiService.generateRequirements(context, docStack, this.userStoryPrompt);

      generated.forEach(req => {
        this.dataService.addRequirement({
          title: req.title,
          description: req.description,
          priority: req.priority,
          status: 'Backlog',
          systemId: sys.id,
          subsystemId: sub.id,
          featureId: feat.id
        });
      });

      this.showAiModal.set(false);
    } finally {
      this.isGenerating.set(false);
    }
  }

  saveManual() {
    // Edit mode
    const editId = this.editingReqId();
    if (editId) {
        this.dataService.updateRequirement(editId, {
            title: this.newReqTitle,
            description: this.newReqDesc,
            priority: this.newReqPriority
        });
        this.showModal.set(false);
        return;
    }

    // Create mode
    const feat = this.selectedFeature();
    if (!feat) return;

    this.dataService.addRequirement({
      title: this.newReqTitle,
      description: this.newReqDesc,
      priority: this.newReqPriority,
      status: 'Backlog',
      systemId: this.dataService.selectedSystemId()!,
      subsystemId: this.dataService.selectedSubsystemId()!,
      featureId: feat.id
    });
    this.showModal.set(false);
  }

  // --- Export Logic ---

  toggleExportFilter() {
     this.includeInProgress.update(v => !v);
     // Re-generate context with new filter
     this.generateExportContext(this.includeInProgress());
  }

  copyPrompt(req?: Requirement) {
      if (req) {
          // Single Requirement Export
          this.generateExportContext(false, req);
          this.showExportModal.set(true);
      } else {
          // Scope Export (Default: ToDo only)
          this.includeInProgress.set(false);
          this.generateExportContext(false);
          this.showExportModal.set(true);
      }
  }

  generateExportContext(includeInProgress: boolean, singleReq?: Requirement) {
    const sys = this.selectedSystem();
    const sub = this.selectedSubsystem();
    const feat = this.selectedFeature();

    let content = 'PROJECT CONTEXT\n===============\n';
    if (sys) content += `System: ${sys.name}\nDescription: ${sys.description}\n\n`;
    if (sub) content += `Subsystem: ${sub.name}\nDescription: ${sub.description}\n\n`;
    if (feat) content += `Feature: ${feat.name}\nDescription: ${feat.description}\n\n`;

    content += 'DOCUMENTATION\n=============\n';
    if (sys?.readme) content += `[SYSTEM: ${sys.name}]\n${sys.readme}\n\n`;
    if (sub?.readme) content += `[SUBSYSTEM: ${sub.name}]\n${sub.readme}\n\n`;
    if (feat?.readme) content += `[FEATURE: ${feat.name}]\n${feat.readme}\n\n`;

    // Add Folders to Context if System
    if (sys?.folders && sys.folders.length > 0) {
        content += `\n[SYSTEM STRUCTURE]\n`;
        sys.folders.forEach(f => {
            content += `- ${f.name} [${f.category}]: ${f.note}\n`;
        });
        content += `\n`;
    }

    if (singleReq) {
      content += 'SELECTED REQUIREMENT\n====================\n';
      content += `Title: ${singleReq.title}\n`;
      content += `Status: ${singleReq.status}\n`;
      content += `Priority: ${singleReq.priority}\n`;
      content += `Description:\n${singleReq.description}\n`;

      content += '\nTASK\n====\n';
      content += `[Generate implementation steps, test cases, or code for: "${singleReq.title}"]\n`;

      this.exportParentId.set(singleReq.id);
      this.exportParentType.set('Requirement');
      this.exportParentName.set(singleReq.title);
      this.pendingExportReqIds.set([]); // No status update for single export? Or should we? Assuming no for now based on req.
    } else {
        // ROLL-UP REQUIREMENTS LOGIC
        const allReqs = this.dataService.requirements();
        let scopeReqs: Requirement[] = [];

        if (feat) {
            scopeReqs = allReqs.filter(r => r.featureId === feat.id);
        } else if (sub) {
            scopeReqs = allReqs.filter(r => r.subsystemId === sub.id);
        } else if (sys) {
            scopeReqs = allReqs.filter(r => r.systemId === sys.id);
        } else {
             scopeReqs = allReqs; 
        }

        // Apply Status Filter
        // Default: ToDo. With Toggle: ToDo + InProgress
        const allowedStatuses: Status[] = includeInProgress ? ['ToDo', 'InProgress'] : ['ToDo'];

        const filteredReqs = scopeReqs.filter(r => allowedStatuses.includes(r.status));
        this.pendingExportReqIds.set(filteredReqs.map(r => r.id));

        if (filteredReqs.length > 0) {
            content += 'SCOPE REQUIREMENTS\n==================\n';
            filteredReqs.forEach((r, index) => {
                content += `${index + 1}. [${r.status}] ${r.title} (Priority: ${r.priority})\n`;
                if (r.description) {
                    content += `   Details: ${r.description.replace(/\n/g, '\n   ')}\n`;
                }
                content += '\n';
            });
        }

        content += 'TASK\n====\n';
        content += '[Enter instruction here, e.g., Implement the requirements listed above, Generate test plan, etc.]\n';

        // Determine parent scope IDs for the session record
        if (feat) {
            this.exportParentId.set(feat.id);
            this.exportParentType.set('Feature');
            this.exportParentName.set(feat.name);
        } else if (sub) {
            this.exportParentId.set(sub.id);
            this.exportParentType.set('Subsystem');
            this.exportParentName.set(sub.name);
        } else if (sys) {
            this.exportParentId.set(sys.id);
            this.exportParentType.set('System');
            this.exportParentName.set(sys.name);
        }
    }

    this.exportContextText.set(content);
  }

  saveExportSession(action: 'copy' | 'download') {
      // 1. Save to DB
      this.dataService.addWorkSession({
          parentId: this.exportParentId(),
          parentType: this.exportParentType(),
          parentName: this.exportParentName(),
          context: this.exportContextText(),
          platform: this.exportPlatform(),
          model: this.exportModel(),
          status: 'Pending'
      });

      // 2. Update Requirements Status
      if (this.pendingExportReqIds().length > 0) {
          this.dataService.batchUpdateRequirementStatus(this.pendingExportReqIds(), 'InProgress');
      }

      // 3. Perform action: copy or download
      if (action === 'copy') {
          navigator.clipboard.writeText(this.exportContextText()).then(() => {
              alert('Session Created! Context copied to clipboard.');
          }).catch(err => {
              console.error('Copy failed', err);
              alert('Session Created, but failed to copy text automatically.');
          });
      } else { // 'download'
          this.downloadContextAsFile();
      }

      // 4. Close & Reset
      this.showExportModal.set(false);
  }

  private downloadContextAsFile() {
    const context = this.exportContextText();
    const parentName = this.exportParentName()
      .replace(/\s+/g, '_') // Replace spaces with underscores
      .replace(/[^a-zA-Z0-9_]/g, '') // Remove non-alphanumeric chars
      .slice(0, 50);
    const timestamp = new Date().toISOString().slice(0, 10);
    const filename = `nebula-session-${parentName}-${timestamp}.md`;

    const blob = new Blob([context], { type: 'text/markdown;charset=utf-8;' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a); // Required for Firefox
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);

    alert('Session Created! Context file is downloading.');
  }
}

import { Component, inject, signal, effect, HostListener, afterNextRender } from '@angular/core';
import { HierarchyNavComponent } from './components/hierarchy-nav.component';
import { KanbanBoardComponent } from './components/kanban-board.component';
import { DataService } from './services/data.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [HierarchyNavComponent, KanbanBoardComponent],
  templateUrl: './app.component.html'
})
export class AppComponent {
  dataService = inject(DataService);

  readonly MIN_SIDEBAR_WIDTH = 224; // w-56
  readonly MAX_SIDEBAR_WIDTH = 600;

  sidebarWidth = signal<number>(288); // Default w-72
  isResizing = signal<boolean>(false);

  constructor() {
    afterNextRender(() => {
        const savedWidth = localStorage.getItem('nebula_sidebar_width');
        if (savedWidth) {
            // Validate saved width
            const numWidth = Number(savedWidth);
            if (numWidth >= this.MIN_SIDEBAR_WIDTH && numWidth <= this.MAX_SIDEBAR_WIDTH) {
                this.sidebarWidth.set(numWidth);
            }
        }
    });

    effect(() => {
      localStorage.setItem('nebula_sidebar_width', String(this.sidebarWidth()));
    });
  }

  startResize(event: MouseEvent): void {
    event.preventDefault();
    this.isResizing.set(true);
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';
  }

  @HostListener('document:mouseup')
  stopResize(): void {
    if (this.isResizing()) {
      this.isResizing.set(false);
      document.body.style.userSelect = 'auto';
      document.body.style.cursor = 'auto';
    }
  }

  @HostListener('document:mousemove', ['$event'])
  onResize(event: MouseEvent): void {
    if (this.isResizing()) {
      const viewSwitcherWidth = 56; // Corresponds to w-14 in Tailwind
      let newWidth = event.clientX - viewSwitcherWidth;

      if (newWidth < this.MIN_SIDEBAR_WIDTH) {
        newWidth = this.MIN_SIDEBAR_WIDTH;
      }
      if (newWidth > this.MAX_SIDEBAR_WIDTH) {
        newWidth = this.MAX_SIDEBAR_WIDTH;
      }
      this.sidebarWidth.set(newWidth);
    }
  }
}

import { Component, inject, computed, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataService } from '../services/data.service';
import { AiService } from '../services/ai.service';
import { Requirement, Status, AI_PLATFORMS, FolderCategory } from '../models/data.models';
import { FormsModule } from '@angular/forms';
import { BoardViewComponent } from './board-view.component';
import { TableViewComponent } from './table-view.component';
import { WorkSessionViewComponent } from './work-session-view.component';

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  imports: [CommonModule, FormsModule, BoardViewComponent, TableViewComponent, WorkSessionViewComponent],
  templateUrl: './kanban-board.component.html'
})
export class KanbanBoardComponent {
  dataService = inject(DataService);
  aiService = inject(AiService);

  searchTerm = signal('');
  showModal = signal(false);
  showAiModal = signal(false);
  showApiKeyModal = signal(false);
  showExportModal = signal(false); // New modal for export
  isGenerating = signal(false);

  // Form State
  editingReqId = signal<string | null>(null);
  newReqTitle = '';
  newReqDesc = '';
  newReqPriority: 'Low' | 'Medium' | 'High' = 'Medium';
  // New modal state for hierarchy selection
  modalSystemId = signal<string | null>(null);
  modalSubsystemId = signal<string | null>(null);
  modalFeatureId = signal<string | null>(null);

  // AI Form State
  userStoryPrompt = '';
  apiKeyInput = '';

  // Export Modal State
  exportContextText = signal('');
  exportPlatform = signal('Cursor');
  exportModel = signal('');
  exportParentId = signal('');
  exportParentType = signal<'System' | 'Subsystem' | 'Feature' | 'Requirement'>('System');
  exportParentName = signal('');
  includeInProgress = signal(false);
  pendingExportReqIds = signal<string[]>([]); // Store IDs to update status later

  // Platform Data (Sorted)
  platforms = Object.keys(AI_PLATFORMS).sort((a, b) => a.localeCompare(b));
  availableModels = computed(() => {
    const models = AI_PLATFORMS[this.exportPlatform()] || [];
    return [...models].sort((a, b) => a.localeCompare(b));
  });

  // Docs Editing State
  editableReadme = signal('');
  importMode: 'append' | 'replace' = 'append';

  // System Folders State (Sorted)
  readonly folderCategories: FolderCategory[] = ['Library', 'Service', 'UI'];
  newFolderName = signal('');
  newFolderCategory = signal<FolderCategory>('Library');
  newFolderNote = signal('');

  // Computed Context
  selectedSystem = computed(() => 
    this.dataService.systems().find(s => s.id === this.dataService.selectedSystemId())
  );

  selectedSubsystem = computed(() => {
    const sys = this.selectedSystem();
    return sys?.subsystems.find(s => s.id === this.dataService.selectedSubsystemId());
  });

  selectedFeature = computed(() => {
    const sub = this.selectedSubsystem();
    return sub?.features.find(f => f.id === this.dataService.selectedFeatureId());
  });

  // Computed properties for modal dropdowns
  modalAvailableSubsystems = computed(() => {
      const sysId = this.modalSystemId();
      if (!sysId) return [];
      const system = this.dataService.systems().find(s => s.id === sysId);
      return system ? system.subsystems : [];
  });

  modalAvailableFeatures = computed(() => {
      const sysId = this.modalSystemId();
      const subId = this.modalSubsystemId();
      if (!sysId || !subId) return [];
      const system = this.dataService.systems().find(s => s.id === sysId);
      const subsystem = system?.subsystems.find(s => s.id === subId);
      return subsystem ? subsystem.features : [];
  });

  // Current Documentation based on selection level
  currentReadme = computed(() => {
    if (this.selectedFeature()) return this.selectedFeature()!.readme || '';
    if (this.selectedSubsystem()) return this.selectedSubsystem()!.readme || '';
    if (this.selectedSystem()) return this.selectedSystem()!.readme || '';
    return '';
  });

  // Check if AI is available
  aiEnabled = computed(() => this.aiService.isConfigured());

  // Effect to update editor when selection changes
  constructor() {
    effect(() => {
        this.editableReadme.set(this.currentReadme());
    });

    // Set default model when platform changes
    effect(() => {
        const models = this.availableModels();
        if (models && models.length > 0) {
            this.exportModel.set(models[0]);
        }
    });
  }

  saveReadme() {
    const content = this.editableReadme();
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (feat && sub && sys) {
        this.dataService.updateFeatureReadme(sys.id, sub.id, feat.id, content);
    } else if (sub && sys) {
        this.dataService.updateSubsystemReadme(sys.id, sub.id, content);
    } else if (sys) {
        this.dataService.updateSystemReadme(sys.id, content);
    }
  }

  // --- Folder Logic ---
  addFolder() {
    const sys = this.selectedSystem();
    if (sys && this.newFolderName().trim()) {
        this.dataService.addSystemFolder(sys.id, {
            name: this.newFolderName(),
            category: this.newFolderCategory(),
            note: this.newFolderNote()
        });
        this.newFolderName.set('');
        this.newFolderNote.set('');
        this.newFolderCategory.set('Library');
    }
  }

  deleteFolder(folderId: string) {
     const sys = this.selectedSystem();
     if (sys) {
         if (confirm('Delete this folder?')) {
            this.dataService.deleteSystemFolder(sys.id, folderId);
         }
     }
  }

  getCategoryClass(category: FolderCategory) {
      switch(category) {
          case 'UI': return 'bg-purple-100 text-purple-800 dark:bg-purple-900/50 dark:text-purple-300';
          case 'Service': return 'bg-blue-100 text-blue-800 dark:bg-blue-900/50 dark:text-blue-300';
          case 'Library': return 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300';
          default: return 'bg-gray-100 text-gray-800';
      }
  }

  triggerImport(mode: 'append' | 'replace', input: HTMLInputElement) {
    this.importMode = mode;
    input.value = ''; // Reset to allow re-selecting same file
    input.click();
  }

  onFileSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input.files?.length) return;

    const file = input.files[0];
    const reader = new FileReader();

    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (this.importMode === 'replace') {
             if (!this.editableReadme() || confirm('This will replace the current documentation. Continue?')) {
                 this.editableReadme.set(text);
             }
        } else {
             const current = this.editableReadme();
             this.editableReadme.set(current ? current + '\n\n' + text : text);
        }
    };
    reader.readAsText(file);
  }

  filteredRequirements = computed(() => {
    let reqs = this.dataService.requirements();
    const fId = this.dataService.selectedFeatureId();
    const sId = this.dataService.selectedSubsystemId();
    const sysId = this.dataService.selectedSystemId();

    // Context Filtering
    if (fId) reqs = reqs.filter(r => r.featureId === fId);
    else if (sId) reqs = reqs.filter(r => r.subsystemId === sId);
    else if (sysId) reqs = reqs.filter(r => r.systemId === sysId);

    // Search Filtering
    const term = this.searchTerm().toLowerCase();
    if (term) {
        reqs = reqs.filter(r => 
            r.title.toLowerCase().includes(term) || 
            r.description.toLowerCase().includes(term)
        );
    }

    return reqs;
  });

  canAddRequirement = computed(() => !!this.selectedFeature());

  openAddModal() {
    this.editingReqId.set(null);
    this.newReqTitle = '';
    this.newReqDesc = '';
    this.newReqPriority = 'Medium';

    // Pre-fill with current context
    this.modalSystemId.set(this.dataService.selectedSystemId());
    this.modalSubsystemId.set(this.dataService.selectedSubsystemId());
    this.modalFeatureId.set(this.dataService.selectedFeatureId());

    this.showModal.set(true);
  }

  openEditModal(req: Requirement) {
    this.editingReqId.set(req.id);
    this.newReqTitle = req.title;
    this.newReqDesc = req.description;
    this.newReqPriority = req.priority;

    // Pre-fill with requirement's own context
    this.modalSystemId.set(req.systemId);
    this.modalSubsystemId.set(req.subsystemId);
    this.modalFeatureId.set(req.featureId);

    this.showModal.set(true);
  }

  openAiModal() {
    if (!this.aiEnabled()) {
        this.apiKeyInput = '';
        this.showApiKeyModal.set(true);
        return;
    }
    this.userStoryPrompt = '';
    this.showAiModal.set(true);
  }

  configureApiKey() {
    if (this.apiKeyInput.trim()) {
        const success = this.aiService.configure(this.apiKeyInput.trim());
        if (success) {
            this.showApiKeyModal.set(false);
            // Do not automatically open the AI generation modal
        } else {
            alert('Failed to configure AI service.');
        }
    }
  }

  async generateAiRequirements() {
    const feat = this.selectedFeature();
    const sub = this.selectedSubsystem();
    const sys = this.selectedSystem();

    if (!feat || !sub || !sys || !this.userStoryPrompt.trim()) return;

    this.isGenerating.set(true);
    const context = `System: ${sys.name}, Subsystem: ${sub.name}, Feature: ${feat.name}`;

    let docStack = '';
    if (sys.readme) docStack += `[SYSTEM DOCS]:\n${sys.readme}\n\n`;
    if (sub.readme) docStack += `[SUBSYSTEM DOCS]:\n${sub.readme}\n\n`;
    if (feat.readme) docStack += `[FEATURE DOCS]:\n${feat.readme}\n\n`;

    try {
      const generated = await this.aiService.generateRequirements(context, docStack, this.userStoryPrompt);

      generated.forEach(req => {
        this.dataService.addRequirement({
          title: req.title,
          description: req.description,
          priority: req.priority,
          status: 'Backlog',
          systemId: sys.id,
          subsystemId: sub.id,
          featureId: feat.id
        });
      });

      this.showAiModal.set(false);
    } finally {
      this.isGenerating.set(false);
    }
  }

  // --- Modal Logic ---

  onModalSystemChange(systemId: string) {
    this.modalSystemId.set(systemId);
    // Cascade reset/update
    const availableSubs = this.modalAvailableSubsystems();
    this.onModalSubsystemChange(availableSubs.length > 0 ? availableSubs[0].id : null);
  }

  onModalSubsystemChange(subsystemId: string | null) {
      this.modalSubsystemId.set(subsystemId);
      // Cascade reset/update
      const availableFeats = this.modalAvailableFeatures();
      this.modalFeatureId.set(availableFeats.length > 0 ? availableFeats[0].id : null);
  }

  saveManual() {
    const sysId = this.modalSystemId();
    const subId = this.modalSubsystemId();
    const featId = this.modalFeatureId();

    if (!sysId || !subId || !featId) {
        alert("A requirement must be linked to a System, Subsystem, and Feature.");
        return;
    }

    const payload = {
        title: this.newReqTitle,
        description: this.newReqDesc,
        priority: this.newReqPriority,
        systemId: sysId,
        subsystemId: subId,
        featureId: featId
    };

    // Edit mode
    const editId = this.editingReqId();
    if (editId) {
        this.dataService.updateRequirement(editId, payload);
    } else {
        // Create mode
        this.dataService.addRequirement({
            ...payload,
            status: 'Backlog',
        });
    }

    this.showModal.set(false);
  }

  // --- Export Logic ---

  toggleExportFilter() {
     this.includeInProgress.update(v => !v);
     // Re-generate context with new filter
     this.generateExportContext(this.includeInProgress());
  }

  copyPrompt(req?: Requirement) {
      if (req) {
          // Single Requirement Export
          this.generateExportContext(false, req);
          this.showExportModal.set(true);
      } else {
          // Scope Export (Default: ToDo only)
          this.includeInProgress.set(false);
          this.generateExportContext(false);
          this.showExportModal.set(true);
      }
  }

  generateExportContext(includeInProgress: boolean, singleReq?: Requirement) {
    const sys = this.selectedSystem();
    const sub = this.selectedSubsystem();
    const feat = this.selectedFeature();

    let content = 'PROJECT CONTEXT\n===============\n';
    if (sys) content += `System: ${sys.name}\nDescription: ${sys.description}\n\n`;
    if (sub) content += `Subsystem: ${sub.name}\nDescription: ${sub.description}\n\n`;
    if (feat) content += `Feature: ${feat.name}\nDescription: ${feat.description}\n\n`;

    content += 'DOCUMENTATION\n=============\n';
    if (sys?.readme) content += `[SYSTEM: ${sys.name}]\n${sys.readme}\n\n`;
    if (sub?.readme) content += `[SUBSYSTEM: ${sub.name}]\n${sub.readme}\n\n`;
    if (feat?.readme) content += `[FEATURE: ${feat.name}]\n${feat.readme}\n\n`;

    // Add Folders to Context if System
    if (sys?.folders && sys.folders.length > 0) {
        content += `\n[SYSTEM STRUCTURE]\n`;
        sys.folders.forEach(f => {
            content += `- ${f.name} [${f.category}]: ${f.note}\n`;
        });
        content += `\n`;
    }

    if (singleReq) {
      content += 'SELECTED REQUIREMENT\n====================\n';
      content += `Title: ${singleReq.title}\n`;
      content += `Status: ${singleReq.status}\n`;
      content += `Priority: ${singleReq.priority}\n`;
      content += `Description:\n${singleReq.description}\n`;

      content += '\nTASK\n====\n';
      content += `[Generate implementation steps, test cases, or code for: "${singleReq.title}"]\n`;

      this.exportParentId.set(singleReq.id);
      this.exportParentType.set('Requirement');
      this.exportParentName.set(singleReq.title);
      this.pendingExportReqIds.set([]); // No status update for single export? Or should we? Assuming no for now based on req.
    } else {
        // ROLL-UP REQUIREMENTS LOGIC
        const allReqs = this.dataService.requirements();
        let scopeReqs: Requirement[] = [];

        if (feat) {
            scopeReqs = allReqs.filter(r => r.featureId === feat.id);
        } else if (sub) {
            scopeReqs = allReqs.filter(r => r.subsystemId === sub.id);
        } else if (sys) {
            scopeReqs = allReqs.filter(r => r.systemId === sys.id);
        } else {
             scopeReqs = allReqs; 
        }

        // Apply Status Filter
        // Default: ToDo. With Toggle: ToDo + InProgress
        const allowedStatuses: Status[] = includeInProgress ? ['ToDo', 'InProgress'] : ['ToDo'];

        const filteredReqs = scopeReqs.filter(r => allowedStatuses.includes(r.status));
        this.pendingExportReqIds.set(filteredReqs.map(r => r.id));

        if (filteredReqs.length > 0) {
            content += 'SCOPE REQUIREMENTS\n==================\n';
            filteredReqs.forEach((r, index) => {
                content += `${index + 1}. [${r.status}] ${r.title} (Priority: ${r.priority})\n`;
                if (r.description) {
                    content += `   Details: ${r.description.replace(/\n/g, '\n   ')}\n`;
                }
                content += '\n';
            });
        }

        content += 'TASK\n====\n';
        content += '[Enter instruction here, e.g., Implement the requirements listed above, Generate test plan, etc.]\n';

        // Determine parent scope IDs for the session record
        if (feat) {
            this.exportParentId.set(feat.id);
            this.exportParentType.set('Feature');
            this.exportParentName.set(feat.name);
        } else if (sub) {
            this.exportParentId.set(sub.id);
            this.exportParentType.set('Subsystem');
            this.exportParentName.set(sub.name);
        } else if (sys) {
            this.exportParentId.set(sys.id);
            this.exportParentType.set('System');
            this.exportParentName.set(sys.name);
        }
    }

    this.exportContextText.set(content);
  }

  saveExportSession(action: 'copy' | 'download') {
      // 1. Save to DB
      this.dataService.addWorkSession({
          parentId: this.exportParentId(),
          parentType: this.exportParentType(),
          parentName: this.exportParentName(),
          context: this.exportContextText(),
          platform: this.exportPlatform(),
          model: this.exportModel(),
          status: 'Pending'
      });

      // 2. Update Requirements Status
      if (this.pendingExportReqIds().length > 0) {
          this.dataService.batchUpdateRequirementStatus(this.pendingExportReqIds(), 'InProgress');
      }

      // 3. Perform action: copy or download
      if (action === 'copy') {
          navigator.clipboard.writeText(this.exportContextText()).then(() => {
              alert('Session Created! Context copied to clipboard.');
          }).catch(err => {
              console.error('Copy failed', err);
              alert('Session Created, but failed to copy text automatically.');
          });
      } else { // 'download'
          this.downloadContextAsFile();
      }

      // 4. Close & Reset
      this.showExportModal.set(false);
  }

  private downloadContextAsFile() {
    const context = this.exportContextText();
    const parentName = this.exportParentName()
      .replace(/\s+/g, '_') // Replace spaces with underscores
      .replace(/[^a-zA-Z0-9_]/g, '') // Remove non-alphanumeric chars
      .slice(0, 50);
    const timestamp = new Date().toISOString().slice(0, 10);
    const filename = `nebula-session-${parentName}-${timestamp}.md`;

    const blob = new Blob([context], { type: 'text/markdown;charset=utf-8;' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a); // Required for Firefox
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);

    alert('Session Created! Context file is downloading.');
  }
}

